	(247, 'ok1rzdfl1mo9mafg9ldthdy8', 'LA IMPLEMENTACIÓN DE LA INTELIGENCIA ARTIFICIAL EN LA REDACCIÓN DE ARTÍCULOS CIENTÍFICOS CUALITATIVOS EN ESTUDIANTES DE LA FACULTAD CIENCIAS DE LA EDUCACIÓN UNA-PUNO-2024.', '2024', 'CIENCIAS DE LA EDUCACIÓN', 'EDUCACION SECUNDARIA', 10000.00, NULL, 'ALANOCA GUTIERREZ REBECA (Responsable)', '2026-05-06 14:06:11.606000', '2026-06-02 16:42:11.027000', '2026-06-02 16:42:11.040000', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	(248, 'lsntdfhm7ihxv1erdcylmgnb', ' PERFIL DE RESISTENCIA BACTERIANA AISLADAS DE LOS RELAVES MINEROS DEL CENTRO POBLADO DE LA MINA LA RINCONADA. PUNO - 2024', '2024', 'CIENCIAS BIOLÓGICAS', 'BIOLOGIA', 10000.00, NULL, 'GONZALES ALCOS VICKY CRISTINA (Responsable)', '2026-05-06 13:56:24.940000', '2026-06-02 16:42:36.989000', '2026-06-02 16:42:37.003000', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	(249, 'iwxhfnr4k1uaq26mimb6r3gk', 'EFECTO DEL PASTOREO EN LA CAPACIDAD DE ALMACENAMIENTO DE CARBONO DE PASTIZALES ALTOANDINOS', '2024', 'CIENCIAS BIOLÓGICAS', 'BIOLOGIA', 10000.00, NULL, 'GUTIERREZ FLORES IVON ROCIO (Responsable)', '2026-05-06 14:05:57.534000', '2026-06-02 16:42:53.798000', '2026-06-02 16:42:53.810000', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	(250, 'aqngybl3c70rxjt6a0y7vn5g', 'CARACTERIZACIÓN DE PAPAS NATIVAS DE LA REGIÓN DE PUNO', '2024', 'CIENCIAS AGRARIAS', 'INGENIERIA AGRONOMICA', 10000.00, NULL, 'LIMA MEDINA ISRAEL (Responsable)', '2026-05-06 14:05:28.882000', '2026-06-02 16:43:15.228000', '2026-06-02 16:43:15.240000', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	(251, 'l7zrbamur1o7rrcp0jiwkd92', 'DESARROLLO DE  PELICULA ACTIVA A BASE DE ALMIDÓN DE CÁSCARA DE PAPA Y EXTRACTO DE ORÉGANO PARA ALARGAR LA VIDA ÚTIL DEL QUESO FRESCO', '2024', 'CIENCIAS AGRARIAS', 'INGENIERIA AGROINDUSTRIAL', 10000.00, NULL, 'CALSIN CUTIMBO MARIENELA (Responsable)', '2026-05-06 14:01:22.830000', '2026-06-02 16:43:24.287000', '2026-06-02 16:43:24.302000', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	(252, 'xit4kbsxqq7ldwynnlczxtx0', 'IDENTIFICACIÓN RÁPIDA DE LA CARNE DE CAMÉLIDOS SUDAMERICANOS MEDIANTE LA VISIÓN POR COMPUTADOR Y REDES NEURONALES CONVOLUCIONALES', '2024', 'CIENCIAS AGRARIAS', 'INGENIERIA AGROINDUSTRIAL', 10000.00, NULL, 'ALVARADO MAMANI ULISES (Responsable)', '2026-05-06 14:29:39.435000', '2026-06-02 16:43:38.357000', '2026-06-02 16:43:38.369000', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	(253, 'era3xh7xw6k1xdxrlewn9emk', 'ANÁLISIS DE LA RADIACIÓN ULTRAVIOLETA Y SUS EFECTOS EN LA SALUD AMBIENTAL DE LA POBLACIÓN DE LA CIUDAD DE PUNO', '2024', 'CIENCIAS BIOLÓGICAS', 'BIOLOGIA', 10000.00, NULL, 'CANALES GUTIERREZ ANGEL (Responsable)', '2026-05-06 14:00:44.000000', '2026-06-02 16:43:45.895000', '2026-06-02 16:43:45.904000', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	(256, 'b7z3rn7uesqxox1rmjkkdfs4', 'DESARROLLO DE TECNOLOGÍA ELECTROQUÍMICA AVANZADA PARA LA PRODUCCIÓN SOSTENIBLE DE HIDRÓGENO VERDE EN EL ALTIPLANO', '2025', 'INGENIERÍA QUÍMICA', 'INGENIERÍA QUÍMICA', 10000.00, NULL, 'DONAIRES FLORES TEOFILO (Responsable)', '2026-05-06 14:55:21.113000', '2026-06-08 21:14:24.885000', '2026-06-08 21:14:24.901000', NULL, 1, NULL, NULL, NULL, NULL, NULL),
	(257, 'd7snunz8a9fw4kpy3km19jrq', 'DESARROLLO Y EVALUACIÓN DE ELECTRODOS AVANZADOS DE TI/PBO₂ PARA LA DEGRADACIÓN ELECTROQUÍMICA DEL COLORANTE LANASET AZUL 2R EN EFLUENTES TEXTILES', '2025', 'INGENIERÍA QUÍMICA', 'INGENIERÍA QUÍMICA', 10000.00, NULL, 'MAMANI QUISPE JOSE NESTOR (Responsable)', '2026-05-06 14:53:03.396000', '2026-06-08 21:14:43.767000', '2026-06-08 21:14:43.778000', NULL, 1, NULL, NULL, NULL, NULL, NULL),
	(258, 's0phmes98onacxxmqnvj04lc', 'EVALUACIÓN DE LA PRODUCCIÓN DE EMBRIONES IN VITRO EN OVINOS CRIOLLOS BAJO CONDICIONES DEL ALTIPLANO PERUANO', '2025', 'MEDICINA VETERINARIA Y ZOOTECNIA', 'MEDICINA VETERINARIA Y ZOOTECNIA', 10000.00, NULL, 'CATACORA FLORES NUBIA LILIA(Responsable)\n', '2026-05-06 15:05:05.762000', '2026-06-08 21:15:54.607000', '2026-06-08 21:15:54.625000', NULL, 1, NULL, NULL, NULL, NULL, NULL),
	(259, 'msq91oo8pp9wrqdthvdlkbd6', 'PREVALENCIA Y ANÁLISIS FILOGENÉTICO DE LOS CÉSTODES EN EL ISPI (ORESTIA ISPI) EXPENDIDOS EN LOS MERCADOS DE LA CIUDAD DE PUNO', '2025', 'MEDICINA VETERINARIA Y ZOOTECNIA', 'MEDICINA VETERINARIA Y ZOOTECNIA', 10000.00, NULL, 'ZAPATA COACALLA CELSO (Responsable)', '2026-05-06 14:45:36.885000', '2026-06-08 21:15:58.975000', '2026-06-08 21:15:58.987000', NULL, 1, NULL, NULL, NULL, NULL, NULL),
	(260, 'jfl26mw9rru0fz2k2b40gcm8', 'GEOFFREY HINTON - IIICCD', '2026', 'INGENIERÍA ESTADÍSTICA E INFORMÁTICA', 'INGENIERÍA ESTADÍSTICA E INFORMÁTICA', 10000.00, 'MODELOS PREDICTIVOS UNI Y MULTIVARIANTES, INGENIERÍA DE SOFTWARE E INTELIGENCIA ARTIFICIAL, ANÁLISIS MULTIVARIADO, BIG DATA, MINERÍA DE DATOS E INVESTIGACIÓN DE MERCADOS', 'QUISPE VARGAS RENATO \nTITO CHURA RENZO ROBIÑO\nNSECA LIZÁRRAGA CINTHIA YANETH\n\n', '2026-08-04 16:42:28.118000', '2026-08-07 13:20:13.074000', NULL, 7, 1, NULL, 'Objetivo General:\nDesarrollar y validar un sistema de inteligencia artificial espacio-temporal y explicable para la predicción probabilística de heladas en la región Puno, capaz de identificar patrones climáticos complejos y generar alertas\n\nObjetivos Específicos:\nOE1. Integrar y preprocesar datos meteorológicos, geográficos y climáticos provenientes de fuentes abiertas para la construcción de una base de datos espaciotemporal orientada a la predicción de heladas en la región Puno.\nOE2. Diseñar e implementar modelos de inteligencia artificial espaciotemporal para identificar patrones climáticos asociados a la ocurrencia de heladas y estimar probabilísticamente su riesgo de ocurrencia.\nOE3. Incorporar técnicas de Inteligencia Artificial Explicable (XAI) para identificar e interpretar la influencia de las variables meteorológicas y geográficas en las predicciones generadas por el sistema.\nOE4. Desarrollar y validar un sistema de alerta temprana que permita visualizar, comunicar y monitorear', 'SISTEMA FROST-PREDICT AI PARA LA ALERTA TEMPRANA DE HELADAS MEDIANTE MODELOS ESPACIO-TEMPORALES EXPLICABLES EN LA REGIÓN PUNO, PERÚ', 'LEONID ALEMAN GONZALES', 93.83),
	(262, 'bgpq4ikyo1oudqwd0r8ulvm8', 'INNOVA SISTEMAS', '2026', 'INGENIERÍA MECÁNICA ELÉCTRICA, ELECTRÓNICA Y SISTEMAS', 'INGENIERÍA DE SISTEMAS', 10000.00, 'INGENIERÍA DE SOFTWARE, BASES DE DATOS E INTELIGENCIA DE NEGOCIOS, INTELIGENCIA ARTIFICIAL, SISTEMAS COMPUTACIONALES Y SISTEMAS BIOINSPIRADOS', 'ANCO COAQUIRA JORGE LUIS\nQUISPE BRAVO EDER ANDER\nPOMA MAQUERA ABAD\nDELGADO JIMENEZ MARIO SAUL\nMACHACA CAHUANA GIANMARCO ALAIN BRUNO\nARISACA TORRES MARK GREGORY\n\n', '2026-08-04 17:06:50.253000', '2026-08-07 13:19:30.937000', NULL, 7, 1, NULL, 'Objetivo General:\nDesarrollar un sistema de detección temprana y alerta de conflictos socioambientales y políticos en Puno mediante procesamiento de lenguaje natural y agentes de inteligencia artificial en n8n.\n\nObjetivos Específicos:\nSeleccionar y caracterizar las fuentes de información digital y APIs de datos públicos locales, evaluando su nivel de confiabilidad para el monitoreo de señales de descontento.\nDiseñar la arquitectura de software orientada a eventos y el sistema de roles secuenciales para el Sistema Multiagente (MAS) integrado como middleware en n8n.\nImplementar flujos automatizados en n8n para la extracción, preprocesamiento y canalización asíncrona datos mediante APIs.\nDesarrollar e integrar los agentes PLN para filtrar e identificar indicadores críticos de conflicto.\nEvaluar experimentalmente la precisión y el tiempo de respuesta del sistema automatizado utilizando el corpus de validación.\n', 'SISTEMA DE DETECCIÓN TEMPRANA DE CONFLICTOS SOCIOAMBIENTALES Y POLÍTICOS EN PUNO MEDIANTE PROCESAMIENTO DE LENGUAJE NATURAL Y UNA ARQUITECTURA BASADA EN AGENTES DE INTELIGENCIA ARTIFICIAL.', 'ALDO HERNAN ZANABRIA GALVEZ', 93.67),
	(264, 'hye7uhfelyl5dx4gf4qbfoce', 'AGROIDET', '2026', 'CIENCIAS AGRARIAS', 'INGENIERÍA AGROINDUSTRIAL', 10000.00, 'INGENIERÍA, TECNOLOGÍA Y GESTIÓN AGROINDUSTRIAL', 'CORNEJO PINTO ANDRES LADISLAO\nMAMANI ARIVILCA YENY ISAURA\nMERMA QUISPE NOHEMY\nCONDORI HUARACHI WILLY ABDEL\nORDOÑEZ ZEA ANEL MAYELI\nUMIÑA MACHACA LEYDI LAURA\n', '2026-08-04 17:07:28.361000', '2026-08-07 13:18:56.890000', NULL, 7, 1, NULL, 'Objetivo General:\nDesarrollar sistema CNN que detecte y clasifique plagas/anomalías en quinua y cañihua, usando imágenes de celular, para apoyar diagnóstico fitosanitario a productores de Puno.\n\nObjetivos Específicos:\nOE1. Construir un dataset de imágenes de quinua y cañihua con categorías de plagas y anomalías representativas del altiplano puneño.\nOE2. Entrenar y optimizar modelos CNN (MobileNetV2 y ResNet-50) mediante transferencia de aprendizaje para la clasificación de plagas y anomalías en los cultivos objetivo.\nOE3. Implementar una herramienta interactiva en que integre el modelo CNN para diagnóstico en tiempo real con recomendaciones de tratamiento fitosanitario', 'SISTEMA DE DETECCIÓN Y CLASIFICACIÓN DE PLAGAS Y ANOMALÍAS EN QUINUA Y CAÑIHUA MEDIANTE REDES NEURONALES CONVOLUCIONALES (CNN) ', 'RONALD ASTETE TEBES', 93.17),
	(266, 'h4roou7g2kfh8a0edtq9fmm9', 'ENERGIAS RENOVABLES', '2026', 'INGENIERÍA QUÍMICA', 'INGENIERÍA QUÍMICA', 10000.00, 'TECNOLOGÍAS AMBIENTALES Y ENERGÍAS RENOVABLES, RECUPERACIÓN, CONSERVACIÓN Y TRANSFORMACIÓN DE RECURSOS NATURALES, ENERGÍAS RENOVABLES', 'CHURAYRA MAMANI, ROSSMERY ANGELA\nACRA ATAMASI, ROSS MERY\nHUAMAN MENDOZA, VANE SHEIRLY\nCONDORI MAMANI, RUTH ALEXANDRA\nIRURI LEON, NATALI LECINCA', '2026-08-04 17:08:58.550000', '2026-08-10 03:44:48.004000', NULL, 7, 1, NULL, 'Objetivo General:\nOptimizar y modelar un sistema híbrido foto-electro-Fenton de flujo continuo para la remoción de Cr(VI) en aguas residuales de curtiembre, evaluando el efecto de los parámetros operativos clave sobre la \n\nObjetivos Específicos:\n•	Caracterizar fisicoquímicamente las aguas residuales de curtiembre mediante la determinación de Cr(VI), cromo total, DQO, pH, conductividad, turbidez, ORP y sólidos suspendidos, a fin de establecer las condiciones iniciales del efluente a tratar.\n•	Evaluar el efecto de la densidad de corriente, la concentración de H₂O₂ y el caudal sobre la remoción de Cr(VI), la reducción de DQO, la turbidez y el consumo energético específico en el sistema híbrido foto-electro-Fenton de flujo continuo.\n•	Optimizar las condiciones operativas del sistema mediante la metodología de superficie de respuesta, estableciendo los valores óptimos de densidad de corriente, concentración de H₂O₂ ', 'OPTIMIZACIÓN Y MODELAMIENTO DE UN SISTEMA HÍBRIDO FOTO-ELECTRO-FENTON EN FLUJO CONTINUO PARA LA REMOCIÓN DE CR(VI) EN AGUAS RESIDUALES DE CURTIEMBRE', 'JOSE NESTOR MAMANI QUISPE', 93.17),
	(268, 'kpvcjcvmv2hrb3fyv9wiriet', 'SEMILLERO DE INVESTIGACIÓN TECNOLÓGICA Y EDUCACIÓN INCLUSIVA – “AXIS”', '2026', 'INGENIERÍA MECÁNICA ELÉCTRICA, ELECTRÓNICA Y SISTEMAS', 'INGENIERÍA DE SISTEMAS', 10000.00, 'INGENIERÍA DE SOFTWARE, BASES DE DATOS E INTELIGENCIA DE NEGOCIOS', 'VARGAS URPI ALBINO\nMONROY QUISPE MARICARMEN\nLLANOS TICONA BLANCA ROSARIO\nRAMOS VILCA FRANCY JIMENA\nFLORES FLORES EMERSON ALDAIR\nSUAÑA HANCCO GUIDO\n\n', '2026-08-04 17:09:30.228000', '2026-08-07 13:18:32.135000', NULL, 7, 1, NULL, 'Objetivo General:\nDiseñar y validar un software con inteligencia artificial para mejorar el tamizaje no invasivo de anemia infantil en Puno, usando imágenes multimodales y corrigiendo la hemoglobina por altitud.\n\nObjetivos Específicos:\nDiseñar la arquitectura modular del sistema para la gestión de datos e inferencia; construir un dataset local anonimizado con imágenes de conjuntiva, palma y lecho ungueal vinculadas a la altitud y hemoglobina de referencia; entrenar y comparar modelos de IA unimodales y multimodales para clasificar la anemia mediante smartphones; analizar el impacto de la corrección altitudinal en el rendimiento del modelo contrastando sus métricas diagnósticas; y desarrollar un prototipo Android offline, evaluando su usabilidad y concordancia mediante una prueba piloto controlada.', 'SISTEMA DE SOFTWARE CON INTELIGENCIA ARTIFICIAL PARA TAMIZAJE NO INVASIVO DE ANEMIA INFANTIL EN POBLACIONES ALTOANDINAS DE PUNO ', 'ALDO HERNAN ZANABRIA GALVEZ', 93.08),
	(270, 'yriu24q9dwie032uas1mns24', 'COMPUGRAPH PUNO', '2026', 'INGENIERÍA MECÁNICA ELÉCTRICA, ELECTRÓNICA Y SISTEMAS', 'INGENIERÍA DE SISTEMAS', 10000.00, 'INTELIGENCIA ARTIFICIAL, SISTEMAS COMPUTACIONALES Y SISTEMAS BIOINSPIRADOS', 'Rojas Luque Franco\nMendoza Macedo José Miguel\nCondori Nina Mildward Erik\nAguilar Anccori Jhon Elias\n\n', '2026-08-04 17:10:10.342000', '2026-08-07 13:18:00.718000', NULL, 7, 1, NULL, 'Objetivo General:\nDesarrollar y validar ANDES-DT, gemelo digital neural con U-Net, Chronos-2 y OpenGL 3.3+ para simular el cambio climático en la ribera del Titicaca.\n\nObjetivos Específicos:\nOE1. Curar el dataset multimodal con Sentinel-2 L2A (2018-2025), SRTM, ERA5 y nivel lacustre SENAMHI.\nOE2. Entrenar el U-Net para segmentación de seis clases sobre chips Sentinel-2 de 256×256 px.\nOE3. Ajustar Chronos-2 y proyectar escenarios SSP2-4.5 y SSP5-8.5 para 2030, 2050 y 2080.\nOE4. Desarrollar la visualización 3D en OpenGL 3.3+ con malla DEM, Phong y timeline.\nOE5. Validar con PSNR, SSIM, LPIPS e IoU sobre el holdout 2023-2025, ANOVA α = 0.05.', 'ANDES-DT: GEMELO DIGITAL NEURAL CON INTELIGENCIA ARTIFICIAL GENERATIVA Y MODELOS DE DIFUSIÓN PARA LA SIMULACIÓN PREDICTIVA 4D DEL CAMBIO CLIMÁTICO EN EL ALTIPLANO PERUANO', 'HUGO YOSEF GOMEZ QUISPE', 91.50),
	(272, 'jdli9ycchtakhp8vpydli948', 'SINERGIA ODONTO-KIDS', '2026', 'CIENCIAS DE LA SALUD', 'ODONTOLOGÍA', 10000.00, 'SALUD DEL RECIÉN NACIDO, NIÑO, ESCOLAR Y ADOLESCENTE', 'Carhuamaca Trujillano Ariana Rachel\nFlores Ccaccallaca Luis Fernando \nTapia Choque Stephany Edith\nAyna Jaliri Leonela Alexandra\nTito Mamani Brayan Steven\n', '2026-08-04 17:10:41.072000', '2026-08-07 13:17:40.540000', NULL, 7, 1, NULL, 'Objetivo General:\nDeterminar la efectividad de una intervención preventiva estratificada según riesgo de caries sobre la evolución de lesiones iniciales de caries en escolares de la I.E.P. N.° 70035 Bellavista, Puno, 2026.\n\nObjetivos Específicos:\n- Comparar la proporción de lesiones iniciales de caries (ICDAS 1 y 2) que presentan remineralización, estabilidad o progresión entre los grupos.\n- Comparar la evolución de las lesiones iniciales de caries según el nivel de riesgo de caries en los escolares participantes\n- Comparar el número promedio de lesiones iniciales de caries por escolar entre los grupos.\n- Comparar el índice de placa bacteriana de Silness y Löe entre los grupos.\n- Comparar los cambios en los hábitos de higiene oral entre los grupos.\n- Comparar los cambios en los conocimientos sobre salud bucal entre los grupos.\n', 'EFECTIVIDAD DE UNA INTERVENCIÓN PREVENTIVA ESTRATIFICADA SEGÚN RIESGO DE CARIES SOBRE LESIONES INICIALES DE CARIES EN ESCOLARES DE LA I.E.P. N.° 70035 BELLAVISTA, PUNO, 2026.', 'VILMA MAMANI CORI', 91.42),
	(274, 'hbpt2pdi164luy3ifuqby4g7', 'ORAL HEALTH RESEARCHERS TEAM (OHRT)', '2026', 'CIENCIAS DE LA SALUD', 'ODONTOLOGÍA', 10000.00, 'SALUD PÚBLICA, CIENCIAS MEDICAS BÁSICAS', 'Tintaya Quispe Evelyn Lizzet\nQuispe Apaza Marco Arnold\nJamachi Ccama Franz Alexis\nAguilar Huanca José Miguel\nCallasaca Tacar Yamilet Gleny\n\n\n', '2026-08-04 17:11:24.721000', '2026-08-07 13:17:16.174000', NULL, 7, 1, NULL, 'Objetivo General:\nEvaluar la actividad antimicrobiana y antifúngica de enjuagues bucales de Minthostachys mollis y Eucalyptus globulus frente a cepas certificadas y aislamientos clínicos orales.\n\nObjetivos Específicos:\n- Determinar la actividad antimicrobiana frente a Streptococcus mutans.\n- Determinar la actividad antimicrobiana frente a Lactobacillus spp.\n- Determinar la actividad antifúngica frente a Candida albicans.\n- Comparar la actividad de las formulaciones hidroalcohólica y de aceites esenciales frente a los microorganismos evaluados\n- Comparar la susceptibilidad de cepas certificadas y aislamientos clínicos frente a las formulaciones de enjuague bucal artesanal evaluadas.\n- Comparar la actividad antimicrobiana y antigungica de las formulaciones respecto al control positivo de Clorhexidina al 0,12 %', 'ACTIVIDAD ANTIMICROBIANA Y ANTIFÚNGICA DE ENJUAGUES BUCALES A BASE DE MINTHOSTACHYS MOLLIS Y EUCALYPTUS GLOBULUS FRENTE A CEPAS CERTIFICADAS Y AISLAMIENTOS CLÍNICOS ORALES DE ESCOLARES ', 'VILMA MAMANI CORI', 91.25),
	(276, 'zzq7lijj79zpogg9hwoyk5xj', 'TRANSFORMANDO LA ALIMENTACIÓN EN PRODUCCIÓN', '2026', 'CIENCIAS AGRARIAS', 'INGENIERÍA AGRONÓMICA', 10000.00, 'DESARROLLO DE SISTEMAS AGROPECUARIOS', 'FLORES FLORES YOSHYA ELIDA\nAPAZA ZELA ELVIS JHASIEL\nPAMPA CHAMBI HUBER ROLANDO\nDIAZ COILA NILBER EDWIN\nAMBROSIO MULLISACA DENILSON SUMI\nONOFRE CACHICATARI EVER POOL\nCHURA CALCINA YESSICA\n\n\n', '2026-08-04 17:13:46.596000', '2026-08-07 13:16:47.953000', NULL, 7, 1, NULL, 'Objetivo General:\nMaximizar la producción y calidad de la leche mediante la optimización energética de la ración, mitigando el balance energético negativo en vacas lecheras durante la época seca en el Centro\n\nObjetivos Específicos:\nEvaluar el consumo de materia seca voluntario y la conversión alimenticia de las vacas lecheras sometidas a los diferentes tratamientos energéticos y niveles de fibra.\nCuantificar el volumen diario de leche producida y la ganancia de peso corporal al inicio y al final del periodo experimental para determinar el rendimiento productivo.\nAnalizar la calidad físico-química y composicional de la leche obtenida en cada ordeño en función de la densidad energética y el porcentaje de fibra suministrado.\nDeterminar la ración óptima que mitigue el balance energético negativo (BEN), asegurando la viabilidad económica y metabólica del hato durante la época de estiaje', 'NUTRICIÓN DE PRECISIÓN ENERGÉTICA EN VACAS LECHERAS: ESTRATEGIA PARA CONTROLAR EL BALANCE ENERGÉTICO NEGATIVO DURANTE LA ÉPOCA SECA', 'RONY ABEL CIPRIAN CARREON', 89.83),
	(278, 'p7jsx01jhxlbvxc7hi76u9o1', 'ARS BAYESIANA', '2026', 'INGENIERÍA ESTADÍSTICA E INFORMÁTICA', 'INGENIERÍA ESTADÍSTICA E INFORMÁTICA', 10000.00, 'MODELOS PREDICTIVOS UNI Y MULTIVARIANTES, INTELIGENCIA ARTIFICIAL, SISTEMAS COMPUTACIONALES Y SISTEMAS BIOINSPIRADOS', 'QUISPE QUISPE RONALDO EDDSON\nQUISPE CALATAYUD NELIDA ARACELY\nCHILI LIMA ANDRE\'E ALESSANDRO\n', '2026-08-04 17:14:11.139000', '2026-08-07 13:11:37.191000', NULL, 7, 1, NULL, 'Objetivo General:\nDeterminar la relación entre la adicción a redes sociales, el estilo de vida y la salud mental en estudiantes de la Universidad Nacional del Altiplano Puno, mediante redes bayesianas\n\nObjetivos Específicos:\n• Describir los niveles de adicción a redes sociales, estilo de vida y salud mental en la muestra de estudiantes universitarios.\n• Determinar la relación entre adicción a redes sociales y salud mental en estudiantes universitarios.\n• Determinar la relación entre adicción a redes sociales y estilos de vida en estudiantes universitarios.\n• Aplicar un modelo de redes bayesianas para identificar la estructura causal conjunta entre la adicción a redes sociales, el estilo de vida y la salud mental en estudiantes de la Universidad Nacional del Altiplano Puno', 'ADICCIÓN A REDES SOCIALES Y SU RELACIÓN CON EL ESTILO DE VIDA Y LA SALUD MENTAL EN ESTUDIANTES DE LA UNIVERSIDAD NACIONAL DEL ALTIPLANO PUNO: UN MODELO DE  REDES BAYESIANAS', 'ANGEL JAVIER QUISPE CARITA', 89.42),
	(280, 'tj4qcbm9cza5mbrovtfvr8ei', 'SEMILLERO DE INVESTIGACIÓN EDUCATIVA YACHAY', '2026', 'CIENCIAS DE LA EDUCACIÓN', 'EDUCACIÓN PRIMARIA', 10000.00, 'PERSPECTIVAS TEÓRICAS DE LA EDUCACIÓN', 'VALERO ANCCO VIDNAY NOEL\nROJAS CASTRO DIANA LIZET \nMACHACA CASTRO YANETH MARIBEL \nRojas Castro Manuel Enrique\nCalcina Quispe Luz Estrella\nCenteno Lipa Feli Isabel \nCaxi Cahui Xiomara María ', '2026-08-04 17:15:48.645000', '2026-08-07 13:15:56.350000', NULL, 7, 1, NULL, 'Objetivo General:\nAnalizar el nivel de alfabetización en inteligencia artificial y su relación con la competencia digital, el pensamiento crítico y el uso responsable de la IA en estudiantes universitarios\n\nObjetivos Específicos:\nIdentificar el nivel de alfabetización en inteligencia artificial en estudiantes universitarios.\nDescribir los niveles de competencia digital, pensamiento crítico y uso responsable de la IA en estudiantes universitarios.\nAnalizar la relación entre la alfabetización en inteligencia artificial, la competencia digital, el pensamiento crítico y el uso responsable de la IA.', 'COMPETENCIA DIGITAL, PENSAMIENTO CRÍTICO Y ALFABETIZACIÓN EN INTELIGENCIA ARTIFICIAL EN ESTUDIANTES UNIVERSITARIOS', 'VIDNAY NOEL VALERO ANCCO', 89.25),
	(282, 'h2to2i4k6dauyl4akie0bjy6', 'SOCIOLOGÍA PARA LA INVESTIGACIÓN ACCIÓN - SOCIOLOGIA', '2026', 'CIENCIAS  SOCIALES', 'SOCIOLOGÍA', 10000.00, 'ECONOMÍA REGIONAL Y LOCAL, DESARROLLO HUMANO Y CALIDAD DE VIDA, PROCESAMIENTO DE ALIMENTOS', 'Jallo Yucra Edwin \nChoquemamani Luque Royer\nLuque Luque Grover Rudy\nCcallo Condori Cristhian Jhoner\nVasquez Sandoval Zenaida Yesica\nHuanca Velasquez Pilar\n', '2026-08-04 17:17:01.817000', '2026-08-07 13:15:33.526000', NULL, 7, 1, NULL, 'Objetivo General:\nDeterminar la relación entre el capital social y las prácticas de innovación en la producción de derivados lácteos en productores rurales de comunidades ubicadas en los distritos de Huata y\n\nObjetivos Específicos:\nDeterminar la relación entre la estructura y el alcance de las redes sociales y las prácticas de innovación en la producción de derivados lácteos en productores rurales de comunidades ubicadas en los distritos de Huata y Acora, Puno.\nDeterminar la relación entre los niveles de confianza social y las prácticas de innovación en la producción de derivados lácteos en productores rurales de comunidades ubicadas en los distritos de Huata y Acora, Puno.\nDeterminar la relación entre las prácticas de reciprocidad y cooperación y las prácticas de innovación en la producción de derivados lácteos en productores rurales de comunidades ubicadas en\n', 'CAPITAL SOCIAL Y PRÁCTICAS DE INNOVACIÓN EN LA PRODUCCIÓN DE DERIVADOS LÁCTEOS DE PRODUCTORES RURALES EN EL DISTRITO DE HUATA Y ACORA, PUNO', 'GUSTAVO MEDINA VILCA', 89.08),
	(284, 'xl9bzk0d8nbm9yud14up6usv', 'INNOVACIÓN EDUCATIVA', '2026', 'CIENCIAS DE LA EDUCACIÓN', 'EDUCACIÓN SECUNDARIA', 10000.00, 'INNOVACIÓN EDUCATIVA Y PRACTICAS PEDAGÓGICAS, DESARROLLO DEL PROCESO PEDAGÓGICO', 'Mamani Quispe Sorayma Sandra\nMachaca Condori Flora Miriam \nLopez Ramos Dino Becker\nNuñez Condori Brainer Jeferson\nCcari Mamani Dante Elmer\nQuispe Morocco Jeidy Zenaida\n', '2026-08-04 17:17:38.549000', '2026-08-07 13:15:04.711000', NULL, 7, 1, NULL, 'Objetivos General: \nDeterminar la contribución de la pedagogía basada en el juego al desarrollo del saber ser en estudiantes del Programa de Lengua, Literatura y Psicología de la Universidad Nacional del Altiplano\n\nObjetivos Específicos:\n1. Diagnosticar el nivel de desarrollo del saber ser en los estudiantes antes de la aplicación de la pedagogía basada en el juego.\n2. Evaluar el nivel de desarrollo del saber ser en los estudiantes después de la aplicación de la pedagogía basada en el juego.\n3. Determinar la contribución de la pedagogía basada en el juego al desarrollo del saber ser mediante la comparación de los resultados obtenidos antes y después de la intervención.', 'LA PEDAGOGÍA BASADA EN EL JUEGO PARA EL DESARROLLO DEL SABER SER EN ESTUDIANTES DEL PROGRAMA DE LENGUA, LITERATURA Y PSICOLOGÍA', 'SILVIA VERONICA VALDIVIA YABAR', 85.58),
	(286, 'p0n8z9li6sme8c34j87q62n8', 'ESENCIA ALTIPLÁNICA', '2026', 'CIENCIAS AGRARIAS', 'INGENIERÍA AGROINDUSTRIAL', 10000.00, 'RECUPERACIÓN, CONSERVACIÓN Y TRANSFORMACIÓN DE RECURSOS NATURALES, INGENIERÍA, TECNOLOGÍA Y GESTIÓN AGROINDUSTRIAL', 'NAIRA APAZA RUTH THANIA\nCCOA CCOA NAYDA YULISA\nCCACCA APAZA FLOR GIMENA', '2026-08-04 17:18:42.825000', '2026-08-07 13:14:40.324000', NULL, 7, 1, NULL, 'Objetivo General: \nDesarrollar una crema fotoprotectora con actividad antioxidante y antiinflamatoria a partir de cushuro y saponinas de quinua\n\nObjetivos Específicos:\n1. Comparar los métodos de maceración hidroetanólica y extracción asistida por microondas para la obtención de extractos antioxidantes de cushuro (Nostoc sphaericum).\n2. Extracción de saponinas de quinua con disolventes eutécticos profundos de cascaras de tres variedades de quinua nativa\n3. Evaluar la actividad antioxidante y antiinflamatoria de formulaciones de crema fotoprotectora con adición de extracto de cushuro y saponinas de quinua', 'DESARROLLO DE UNA CREMA FOTOPROTECTORA CON ACTIVIDAD ANTIOXIDANTE Y ANTIINFLAMATORIA A PARTIR DE CUSHURO Y SAPONINAS DE QUINUA', 'MARIANELA CALSIN CUTIMBO', 88.58),
	(288, 'se05ym58f90djl8o7dfbng65', 'SEMILLERO DE INVESTIGACIÓN ETNOMATEMÁTICA Y SABERES ANDINOS (SIESA)', '2026', 'CIENCIAS DE LA EDUCACIÓN', 'EDUCACIÓN SECUNDARIA', 10000.00, 'INTERDISCIPLINARIEDAD EN LA DINÁMICA EDUCATIVA: TEORÍA Y MÉTODOS DE INVESTIGACIÓN DE LA DIDÁCTICA DE LA MATEMÁTICA', 'Chura Humora Edgar\nApaza Umpire Jackeline\nCondori Paricahua Ximena Aracely\n', '2026-08-04 17:21:01.075000', '2026-08-07 13:14:18.780000', NULL, 7, 1, NULL, 'Objetivo General:\nAnalizar las nociones de probabilidad presentes en la lectura de la hoja de coca practicada por los yatiris del altiplano puneño desde una perspectiva etnomatemática.\n\nObjetivos Específicos:\n− Describir las etapas, procedimientos y significados culturales que intervienen en la lectura de la hoja de coca practicada por los yatiris.\n− Identificar formas de razonamiento vinculadas a la incertidumbre, la valoración de posibilidades y la interpretación de acontecimientos futuros presentes en la práctica ritual.\n− Analizar las nociones probabilísticas implícitas que emergen durante los procesos de interpretación desarrollados por los yatiris.\n− Interpretar los hallazgos identificados a partir de los fundamentos teóricos del Programa Etnomatemática.', 'NOCIONES DE PROBABILIDAD EN LA LECTURA DE LA HOJA DE COCA: UN ESTUDIO ETNOMATEMÁTICO CON YATIRIS DEL ALTIPLANO PUNEÑO', 'BETHZABE COTRADO MENDOZA', 88.25),
	(290, 'jn4l97rwq72wmt1fz3t1xxx2', 'YUYAY, CULTURA Y COGNICIÓN', '2026', 'CIENCIAS  SOCIALES', 'DEPARTAMENTO DE HUMANIDADES', 10000.00, 'SOCIOLINGÜÍSTICA E INTERCULTURALIDAD', 'Yto Goyzueta Andy Veicker\nCanaza Huacasi Cesar Augusto\nCajia Mamani Jerry Wuelfredo\nMamani Castrillo Noe Lizardo\nMamani Ariaca Milagros Juana\nCastillo Apaza Fanny Esther', '2026-08-04 17:22:43.161000', '2026-08-10 03:42:18.677000', NULL, 7, 1, NULL, 'Objetrvo General:\nComprender las narrativas de sufrimiento psíquico y las experiencias de transición sociocultural en estudiantes universitarios de origen rural en la Universidad Nacional del Altiplano\n\nObjetivos Específicos:\nDescribir las experiencias de transición sociocultural y los significados atribuidos al sufrimiento psíquico durante la incorporación a la vida universitaria.\nIdentificar en las narrativas estudiantiles los factores socioculturales de vulnerabilidad asociados al riesgo suicida, tales como el desarraigo, discriminación, aislamiento y tensiones identitarias.\nReconocer los recursos de resistencia cultural, saberes ancestrales y estrategias de afrontamiento colectivo desplegados por los estudiantes para sostener su bienestar.\nProponer lineamientos institucionales para el diseño de estrategias de prevención del riesgo suicida con pertinencia cultural en la Universidad Nacional del Altiplano.', '"ENTRE DOS MUNDOS: NARRATIVAS DE SUFRIMIENTO PSÍQUICO Y TRANSICIÓN SOCIOCULTURAL EN ESTUDIANTES DE ORIGEN   RIURAL DE LA UNA PUNO. APORTES PARA PREVENIR LA CONDUCTA SUICIDA"  ', 'MARIBEL CEFERINA PUMACAHUA YUCRA', 87.92),
	(292, 'z89z1brfurealxlgy3vdfqyt', 'RAICES HUMANAS', '2026', 'CIENCIAS  SOCIALES', 'ANTROPOLOGÍA', 10000.00, 'CULTURA ANDINA, SOCIEDAD Y MEDIOAMBIENTE', 'SUAÑA FLORES CRISTHIAN\nMIRANDA TINTA ALEXANDER\nDIAZ CUTIPA ROXANA NILVIA\nZAPANA PEREZ KAREN GABRIELA\nTITO CCAPA JESSICA ROSSY\nCALIZAYA BALCONA LIBERTAD NAYESKA', '2026-08-04 17:24:14.869000', '2026-08-07 13:13:46.226000', NULL, 7, 1, NULL, 'Objetivo General:\nAnalizar las transformaciones de la cultura alimentaria andina en términos de prácticas, significados e influencias contemporáneas, en la alimentación de los estudiantes de Antropología de la Universidad Nacional del Altiplano\n\nObjetivos Específicos:\n- Identificar las prácticas alimentarias predominantes en los estudiantes de Antropología.\n- Interpretar los significados culturales que los estudiantes atribuyen a la alimentación tradicional y moderna.\n- Examinar las influencias contemporáneas que inciden en las prácticas alimentarias de los estudiantes.\n- Analizar la relación entre prácticas alimentarias y significados culturales en el contexto de transformación alimentaria.', 'TRANSFORMACIONES DE LA CULTURA ALIMENTARIA ANDINA: PRÁCTICAS, SIGNIFICADOS E INFLUENCIAS CONTEMPORÁNEAS EN LA ALIMENTACIÓN DE ESTUDIANTES DE ANTROPOLOGÍA DE LA UNIVERSIDAD NACIONAL DEL ALTIPLANO PUNO', 'DAVID ELEAZAR BARRA QUISPE', 87.53),
	(294, 'jhb9r52g351nxmcd4vbxew0v', 'SEMILLERO DE INVESTIGACIÓN, INNOVACIÓN Y UNIÓN SOCIAL” (SIRIUS)', '2026', 'TRABAJO SOCIAL', 'TRABAJO SOCIAL', 10000.00, 'DESARROLLO HUMANO Y CALIDAD DE VIDA', 'MAMANI FLORES YÓMELY NAZIRA\nMAMANI TORRES BEATRIZ\nTURPO MAMANI FIORELA MAGALY\n', '2026-08-04 17:24:41.356000', '2026-08-07 13:13:13.815000', NULL, 7, 1, NULL, 'Objetivo General:\nAnalizar la relación entre los entornos digitales y el bienestar socioemocional de los estudiantes de educación secundaria de las instituciones educativas GUE San Carlos e IES Carlos Rubina Burgos\n\nObjetivos Específicos:\n• Identificar los patrones de uso de entornos digitales (redes sociales y plataformas digitales) de los estudiantes de educación secundaria de la ciudad de Puno.\n• Describir el nivel de bienestar socioemocional, considerando los indicadores de ansiedad, depresión y autoestima, en los estudiantes de educación secundaria de la ciudad de Puno.\n• Determinar el grado de relación entre el uso de entornos digitales y el bienestar socioemocional (ansiedad, depresión y autoestima) de los estudiantes de educación secundaria de la ciudad de Puno.\n• Proponer lineamientos de orientación socioeducativa que favorezcan una relación saludable entre los estudiantes y los entornos digitales\n', 'ENTORNOS DIGITALES Y BIENESTAR SOCIOEMOCIONAL: UN ESTUDIO SOBRE LA SALUD MENTAL EN ESTUDIANTES DE SECUNDARIA DE LA CIUDAD DE PUNO', 'ZEZY YADEYDA SARDON ARI', 87.58),
	(296, 'p3cqkyt51x1m7g90h352r9xs', '“SEMILLERO DE INVESTIGACIÓN EN DISEÑO DE MATRICES ALIMENTARIAS FUNCIONALES (SI- DMAF)”', '2026', 'CIENCIAS AGRARIAS', 'INGENIERÍA AGROINDUSTRIAL', 10000.00, 'INGENIERÍA, TECNOLOGÍA Y GESTIÓN AGROINDUSTRIAL, PROCESAMIENTO DE ALIMENTOS', 'Lira Pinazo Paola Rosario\nTorres Vargas Dana Cielo\nYucra Callamullo Yakelin\nYucra López Samuel Valentín\n', '2026-08-04 17:25:10.731000', '2026-08-07 13:12:46.198000', NULL, 7, 1, NULL, 'Objetivo General:\nDesarrollar un ingrediente funcional en polvo a partir de fresas de altura mediante un sistema híbrido de secado por ventana de refractancia y microondas, evaluando su influencia sobre sus propiedades.\n\nObjetivos Específicos:\nDeterminar el efecto de la temperatura y tiempo de secado por ventana de refractancia y de la potencia de microondas, sobre las características de deshidratación de las fresas de altura.\nEvaluar las propiedades fisicoquímicas del ingrediente funcional en polvo obtenido mediante un sistema híbrido de secado por ventana de refractancia y microondas.\nAnalizar las propiedades físicas y colorimétricas del ingrediente funcional en polvo obtenido a partir de fresas de altura mediante un sistema híbrido de secado por ventana\nCuantificar la retención de vitamina C, compuestos fenólicos totales, antocianinas y capacidad antioxidante del ingrediente funcional en polvo obtenido.', '“VALORIZACIÓN DE FRESAS (FRAGARIA × ANANASSA) DE ALTURA MEDIANTE LA OBTENCIÓN DE UN INGREDIENTE FUNCIONAL EN POLVO UTILIZANDO UN SISTEMA HÍBRIDO DE SECADO POR VENTANA"', 'WENCESLAO TEDDY MEDINA ESPINOZA', 87.50),
	(298, 'ijwl73psgro8351y72wubmwo', 'SEMILLERO"GENERACCIONSOCIAL', '2026', 'TRABAJO SOCIAL', 'TRABAJO SOCIAL', 10000.00, 'DERECHOS HUMANOS Y FORTALECIMIENTO DEMOCRÁTICO', 'Balcona Chambilla Lorena Britney\nBLANCO MEZA LEONOR NICOLE\nCOILA CHOQUE SIDNEY YANIRA\nESQUERRE YANA JUAN ANTHONY\nJALLO HUANCAVILCA MILAGROS YOSY\nUMIÑA NUÑEZ MAYTE LORENA\n', '2026-08-04 17:25:45.254000', '2026-08-07 13:12:09.433000', NULL, 7, 1, NULL, 'Objetivo General:\nDeterminar la relación entre la gobernanza algorítmica y las brechas de acceso a servicios públicos digitales en los pobladores del Centro Poblado Menor de Llachón, distrito de Capachica, Puno, 2026.\n\nObjetivos Específicos:\n- Identificar la relación entre la legitimidad de entrada de la  algorítmica y las brechas de acceso a servicios públicos digitales en los pobladores del Centro Poblado Menor de Llachón,\n- Describir la relación entre la legitimidad del proceso de la gobernanza algorítmica y las brechas de acceso a servicios públicos digitales en los pobladores\n-Establecer la relación entre la legitimidad de los resultados de la gobernanza algorítmica y las brechas de acceso a servicios públicos digitales en los pobladores', 'GOBERNANZA ALGORÍTMICA Y BRECHAS DE ACCESO A SERVICIOS PÚBLICOS DIGITALES EN POBLADORES DEL CENTRO POBLADO MENOR DE LLACHÓN, CAPACHICA, PUNO, 2026.', 'SOLEDAD JACKELINE ZEGARRA UGARTE', 87.50),
	(300, 'e57yqe4savtlveavquvzmkzg', 'IMPACTO DE LA EDUCACIÓN AMBIENTAL EN EL CONSUMO DE AGUA EN INSTITUCIONES EDUCATIVAS EN LA CIUDAD DE PUNO – “EDUAGUA PUNO”', '2026', 'INGENIERÍA AGRÍCOLA', 'INGENIERÍA AGRÍCOLA', 10000.00, 'CONSERVACIÓN Y APROVECHAMIENTO DE RECURSOS NATURALES, RESPONSABILIDAD SOCIAL DE LA EDUCACIÓN, RECURSOS HÍDRICOS', 'Zurita Zurita Brayan Dante\nHuanca Tito Wilber Jesús\nChipana Choque Ana Luz\nTurpo Almanza Jherson Denis Abel\nVilca Tapia Alex Franklin\n\n', '2026-08-04 17:26:27.302000', '2026-08-07 13:22:55.071000', NULL, 7, 1, NULL, 'Objetivo General:\nEvaluar el impacto de la educación ambiental en el consumo de agua en instituciones educativas de la ciudad de Puno.\n\nObjetivos Específicos:\nAnalizar los hábitos de consumo de agua en instituciones educativas seleccionadas.\nEvaluar el nivel de conocimiento ambiental de estudiantes.\nDeterminar los cambios en el consumo de agua tras la implementación de acciones educativas.\nProponer estrategias educativas para el uso responsable del agua.', 'EVALUACIÓN DEL IMPACTO DE LA EDUCACIÓN AMBIENTAL EN EL CONSUMO HÍDRICO ESCOLAR: UN ANÁLISIS COMPARATIVO EN LA CIUDAD DE PUNO', 'JOSE ANTONIO MAMANI GOMEZ', 86.83),
	(302, 'ugqqno2o5chbyx4z655b2nyl', 'CLIMATECH UNA PUNO', '2026', 'INGENIERÍA  MECÁNICA  ELÉCTRICA, ELECTRÓNICA Y SISTEMAS', 'INGENIERÍA DE SISTEMAS', 10000.00, 'INTELIGENCIA ARTIFICIAL, SISTEMAS COMPUTACIONALES Y SISTEMAS BIOINSPIRADOS', 'Chura Yupa Franklin Alfred\nMayta Guzman Fabricio \nTipo Catunta Roy Jesus Aldair', '2026-08-04 17:28:00.811000', '2026-08-07 13:20:44.702000', NULL, 7, 1, NULL, 'Objetivo General:\nDesarrollar y validar una arquitectura híbrida de IA generativa con Transformers fundacionales e indexación multidimensional para el pronóstico en tiempo real de fenómenos meteorológicos extremos en el Altiplano peruano.\n\nObjetivos Específicos:\nOE1. Construir un dataset multimodal para Puno cruzando SENAMHI, Open-Meteo, GOES-R y ERA5 (2015-2025).\nOE2. Implementar la capa de persistencia con R*-Tree sobre MongoDB frente a B-Tree de control, con Octree 3D como prueba de concepto.\nOE3. Ejecutar fine-tuning de Chronos-2 sobre telemetría andina y evaluar Pangu-Weather como baseline neuronal vía ECMWF ai-models.\nOE4. Comparar la arquitectura propuesta contra el WRF 25 km del SENAMHI mediante MAE, RMSE, CRPS y skill score, con ANOVA de medidas repetidas.', 'INTELIGENCIA ARTIFICIAL GENERATIVA Y TRANSFORMERS PARA EL PRONÓSTICO EN TIEMPO REAL DE FENÓMENOS METEOROLÓGICOS EXTREMOS EN EL ALTIPLANO PERUANO', 'HUGO YOSEF GOMEZ QUISPE', 86.83),
	(304, 'c480r0vmwignc1c5w2fkm0hv', 'SEMILLERO DE INVESTIGACION EN SEGURIDAD DE INFORMACION', '2026', 'INGENIERÍA MECÁNICA ELÉCTRICA, ELECTRÓNICA Y SISTEMAS', 'INGENIERÍA DE SISTEMAS', 10000.00, 'DESARROLLO, GESTIÓN, SEGURIDAD Y AUDITORIA DE SISTEMAS DE INFORMACIÓN', 'TICONA YANQUI, FIDEL ERNESTO', '2026-08-04 17:28:45.473000', '2026-08-10 04:03:14.053000', NULL, 7, 1, NULL, 'Objetivo General:\nAnalizar el riesgo de ciberseguridad estudiantil mediante modelos de inteligencia artificial, identificando factores, patrones y niveles de exposición digital para generar conocimiento y orientar soluciones preventivas en la UNAP\n\nObjetivos Específicos:\n● Identificar los factores de riesgo de ciberseguridad en estudiantes de la Universidad Nacional del Altiplano de Puno, considerando hábitos digitales, contraseñas, información personal, redes, plataformas y dispositivos.\n● Determinar el nivel de riesgo mediante el análisis de amenazas digitales, vulnerabilidades, prácticas de seguridad e incidentes informáticos.\n● Establecer relaciones entre factores de riesgo y comportamientos digitales que aumentan o reducen la vulnerabilidad estudiantil.\n● Aplicar modelos de inteligencia artificial para reconocer patrones, clasificar, predecir o agrupar perfiles de riesgo.\n● Formular lineamientos teóricos y preventivos que orienten futuras acciones de ciberseguridad en estudiantes universitarios.', 'ANÁLISIS DEL RIESGO DE CIBERSEGURIDAD MEDIANTE MODELOS DE INTELIGENCIA ARTIFICIAL EN ESTUDIANTES DE LA UNIVERSIDAD NACIONAL DEL ALTIPLANO DE PUNO, 2026', 'FIDEL ERNESTO TICONA YANQUI', 86.17),
	(306, 's1ujhwujmght3jjndrqu6l3g', 'SEMILLEROS DE SERENDIPIA EN TRABAJO SOCIAL', '2026', 'TRABAJO SOCIAL', 'TRABAJO SOCIAL', 10000.00, 'INSTITUCIONALIDAD, CONFLICTOS Y GESTIÓN AMBIENTAL', 'Mamani Rayme Jane Javelin \nQuispe Huahuacondori Edward Jhon\nTotora Gutierrez Griselda \nBenavente Ticona Yoselim Adai \nFlores Ordoño Daysi Maribel \nQuispe Itusaca Katy Carolina', '2026-08-04 17:30:59.695000', '2026-08-07 13:22:32.728000', NULL, 7, 1, NULL, 'Objetivo General:\nComprender las representaciones institucionales y los discursos de la sociedad civil sobre la gestión ambiental del Lago Titicaca, identificando las brechas entre la normativa y la práctica, así como las\n\nObjetivos Específicos:\na. Interpretar los discursos y narrativas construidas por los representantes del Estado (municipalidades, Gobierno Regional, Ministerio del Ambiente) sobre la contaminación y la gestión de\náreas degradadas del Lago Titicaca.\nb. Explorar las percepciones de las organizaciones de la sociedad civil (ONGs, asociaciones ambientales) respecto a la pertinencia y eficacia de las políticas públicas ambientales.\nc. Develar las brechas y contradicciones existentes entre la normativa ambiental y las prácticas reales de gestión en el territorio.\nd. Analizar las percepciones de los actores institucionales y sociales sobre la participación comunitaria en la gestión ambiental del Lago Titicaca.\ne. Contrastar los puntos', 'REPRESENTACIONES INSTITUCIONALES Y POLÍTICAS PÚBLICAS SOBRE LA GESTIÓN AMBIENTAL DEL LAGO TITICACA', 'MARIA EMMA ZUÑIGA VASQUEZ', 86.17),
	(308, 'ds0msvlqjrylgx1pfzcos4mj', 'RESILIENCIA COMUNITARIA Y CULTURA DE PREVENCIÓN EN EL CERRO AZOGUINE – “PREVENCIÓNAZOGUINE”', '2026', 'INGENIERÍA AGRÍCOLA', 'INGENIERÍA AGRÍCOLA', 10000.00, 'GESTIÓN DE RIESGOS Y CAMBIO CLIMÁTICO, ORDENAMIENTO TERRITORIAL Y MEDIO AMBIENTE', 'Quispe Vilcanqui , Juan Carlos\nLope Lope, Freddy Clinton\nAcero Ramos, Viviana Balbina\nHuillca Pari , Daniel Mathias\nContreras Atencio, Eva Yonmy', '2026-08-04 17:31:39.675000', '2026-08-10 04:01:59.653000', NULL, 7, 1, NULL, 'Objetivo General:\nAnalizar la resiliencia comunitaria y la cultura de prevención frente a riesgos socioambientales en la población del cerro Azoguine.\n\nObejtivos Específicos:\nIdentificar los principales riesgos y amenazas presentes en el cerro Azoguine.\nEvaluar el nivel de resiliencia comunitaria ante situaciones de emergencia.\nAnalizar la percepción del riesgo y las prácticas de prevención de la población.\nProponer estrategias para el fortalecimiento de la cultura de prevención comunitaria.', 'ESTRATEGIAS DE FORTALECIMIENTO DE LA CULTURA DE PREVENCIÓN COMUNITARIA ANTE DESASTRES NATURALES EN EL SECTOR AZOGUINE', 'JOSE ANTONIO MAMANI GOMEZ', 85.92),
	(310, 'sikow02ofprpcbwpk2in7ez8', 'EXDUCERE', '2026', 'CIENCIAS DE LA EDUCACIÓN', 'EDUCACIÓN SECUNDARIA', 10000.00, 'GESTIÓN EDUCATIVA Y DESARROLLO INSTITUCIONAL', 'ARIAS LIZARES, ANDRES', '2026-08-04 17:32:38.614000', '2026-08-10 04:00:25.094000', NULL, 7, 1, NULL, 'Objetivo General:\nAnalizar las diferencias en el nivel de comprensión del desarrollo de competencias entre los estudiantes de las áreas biomédicas, sociales e ingenierías de la Universidad Nacional del Altiplano de Puno.\n\nObjetivos Específicos:\nPrecisar las diferencias existentes en la comprensión conceptual sobre las competencias entre los estudiantes de las áreas biomédicas, sociales e ingenierías de la Universidad Nacional del Altiplano de Puno.\nEstablecer las diferencias existentes en la comprensión del proceso de desarrollo de competencias entre los estudiantes de las áreas biomédicas, sociales e ingenierías de la Universidad Nacional del Altiplano de Puno.\nExaminar las diferencias en la comprensión de la evaluación por competencias entre los estudiantes de las áreas biomédicas, sociales e ingenierías de la Universidad Nacional del Altiplano de Puno.\nIdentificar las diferencias en la comprensión de la aplicabilidad de las ', 'DIFERENCIAS EN LA COMPRENSIÓN DEL DESARROLLO DE COMPETENCIAS ENTRE ESTUDIANTES DE LAS ÁREAS BIOMÉDICAS, SOCIALES E INGENIERÍAS DE LA UNIVERSIDAD NACIONAL DEL ALTIPLANO', 'ANDRES ARIAS LIZARES', 85.00),
	(312, 'erj30udo43dpzbcv4prsav8m', '“SEMILLERO DE INVESTIGACIÓN MONTESSORI” (SIM)', '2026', 'CIENCIAS DE LA EDUCACIÓN', 'EDUCACIÓN PRIMARIA', 10000.00, 'PERSPECTIVAS TEÓRICAS DE LA EDUCACIÓN, RESPONSABILIDAD SOCIAL DE LA EDUCACIÓN', 'HUMPIRI PACOMPIA , EDWIN\nAGUILAR CHOQUEHUANCA , SHAYLA YESSICA\nAYNA CONDORI , DANITZA\nCOTRADO CONDORI , YESSICA DEYSI', '2026-08-04 17:33:03.304000', '2026-08-10 03:59:20.885000', NULL, 7, 1, NULL, 'Objetivo General:\nDeterminar el efecto que tiene la implementación de entornos lúdicos en el fortalecimiento de las competencias socioemocionales y en el desarrollo del pensamiento crítico matemático en los estudiantes \n\nObjetivos Específicos:\n-Analizar la influencia que ejerce la aplicación de espacios lúdicos en el fortalecimiento de las competencias socioemocionales.\n-Identificar el impacto de la incorporación de entornos lúdicos en el desarrollo del pensamiento crítico matemático en los estudiantes.\n-Contrastar los resultados obtenidos en el pretest y el postest con el fin de evidenciar variaciones en el nivel de desarrollo de las habilidades socioemocionales en los estudiantes.\n-Comparar diferencias entre los resultados del pretest y el postest para determinar cambios en el desarrollo del pensamiento matemático en los estudiantes.', 'LOS ESPACIOS LÚDICOS EN EL DESARROLLO DE HABILIDADES SOCIALES Y EL PENSAMIENTO MATEMÁTICO EN LOS NIÑOS DE EDUCACIÓN PRIMARIA', 'DANITZA LUISA SARDON ARI', 84.83),
	(314, 'bgw8wb0xu7snetamf28yjwtw', 'AYLLU DEL SABER: UNIDOS POR LA INVESTIGACIÓN EDUCATIVA', '2026', 'CIENCIAS DE LA EDUCACIÓN', 'EDUCACIÓN SECUNDARIA', 10000.00, NULL, 'Parillo Pineda, Fiorela Felicitas\nIlaquita Mamani , Jacobo Orestes\nLaura Apaza, Erika Yuly\nApaza Cabrera , Yeraldine Marina', '2026-08-04 17:33:32.481000', '2026-08-10 03:58:05.097000', NULL, 7, 1, NULL, 'Objetivo General:\nDescribir los sesgos de género en la elección de carreras STEM en estudiantes de educación secundaria de la ciudad de Puno en el año 2026.\n\nObjetivos Específicos:\n•	Identificar las creencias estereotipadas de género asociadas a las carreras STEM. \n•	Describir el nivel de autoeficacia percibida en áreas STEM. \n•	Caracterizar las percepciones sobre roles de género en la elección de carrera profesional. \n•	Describir las expectativas familiares y sociales vinculadas a la elección de carreras STEM. ', '“SESGOS DE GÉNERO EN LA ELECCIÓN DE CARRERAS STEM EN ESTUDIANTES DE EDUCACIÓN SECUNDARIA DE LA CIUDAD DE PUNO, 2026”', 'INDIRA IRACEMA GOMEZ ARTETA', 84.58),
	(316, 'tunglajczpt3gj9fhjakfsyk', 'ODONTOCIENCIA Y SALUD', '2026', 'CIENCIAS DE LA SALUD', 'ODONTOLOGÍA', 10000.00, 'DIAGNÓSTICO, TRATAMIENTO Y REHABILITACIÓN DEL SISTEMA ESTOMATOGNÁTICO', 'ACERO JIMENEZ LEYDI GIOVANNA\nESCOBAR MAMANI YADHIRA LIZBETH\nMAYTA FLORES LIZBETH NAYELI\nMAMANI RIOS HOLINDA\nCOPACONDORI RAMOS GLISETH GLIS\n\n\n', '2026-08-04 17:35:52.979000', '2026-08-07 13:22:02.924000', NULL, 7, 1, NULL, 'Objetivo General:\nEvaluar el efecto de las infusiones tradicionales altoandinas (muña, coca y eucalipto) sobre la estabilidad cromática de resinas compuestas mediante un estudio experimental in vitro.\n\nObjetivos Específicos:\n- Determinar la estabilidad cromática de las resinas compuestas expuestas a infusión de muña (Minthostachys mollis) durante 1 día, 3 días, 5 y 7 días.\n- Determinar la estabilidad cromática de las resinas compuestas expuestas a infusión de coca (Erythroxylum coca) durante 1 día, 3 días, 5 y 7 días.\n- Determinar la estabilidad cromática de las resinas compuestas expuestas a infusión de eucalipto (Eucalyptus globulus) durante 1 día, 3 días, 5 y 7 días.\n- Comparar la estabilidad cromática de las resinas compuestas expuestas a las diferentes infusiones tradicionales altoandinas y al grupo control según el tiempo de exposición.', 'EFECTO DE INFUSIONES TRADICIONALES ALTOANDINAS SOBRE LA ESTABILIDAD CROMÁTICA DE RESINAS COMPUESTAS, PUNO PERÚ', 'NELLY BEATRIZ QUISPE MAQUERA', 84.58),
	(318, 'ptwvfgjrp6okx17mfvnqv3l8', 'GRUPO DE INVESTIGACIONES ANTROPOLÓGICAS - GIA', '2026', 'CIENCIAS  SOCIALES', 'ANTROPOLOGÍA', 10000.00, 'ANÁLISIS DE PROCESOS SOCIALES, FAMILIAS: REALIDADES, CAMBIO Y DINÁMICAS DE INTERVENCIÓN', 'Quispe Condori Tamara Akemi\nPanca Quispe Sarely Betsi\nTarqui Tique Lizet Lucero\nCcama Llatasi Jherson Jhoseph\nMaquera Apaza Ruth Mayely\n', '2026-08-04 17:37:08.237000', '2026-08-07 13:21:36.063000', NULL, 7, 1, NULL, 'Objetivo General:\nAnalizar las trayectorias de estudiantes peruanos que se movilizan por estudios superiores en universidades en el país de Bolivia\n\nObjetivos Específicos:\n1. Identificar las características socioeconómicas de los estudiantes peruanos que realizan estudios de educación superior en Bolivia.\n2. Analizar los factores sociales, económicos y educativos que influyen en la decisión de los estudiantes peruanos de realizar estudios superiores en Bolivia\n3. Describir las dificultades, problemáticas y oportunidades de los estudiantes universitarios peruanos en Bolivia durante y después de los estudios superiores', 'TRAYECTORIAS FORMATIVAS DE ESTUDIANTES PERUANOS EN BOLIVIA: DESAFÍOS, OPORTUNIDADES Y EXPECTATIVAS DE FUTURO', 'DUVERLY JOAO INCACUTIPA LIMACHI', 84.42),
	(320, 'wytsfji4j2j3fmpy9b53r2s8', 'SEMILLERO DE INVESTIGACIÓN EN EDUCACIÓN FÍSICA Y LIDERAZGO FEMENINO” (SIEFLF)', '2026', 'CIENCIAS DE LA EDUCACIÓN', 'EDUCACION FISICA', 10000.00, 'PSICOMOTRICIDAD', 'MAYTA DE LA RIV ZENAYDA LUCERO \nMAMANI ALMONTE YOMARA NOELIA\nCOLQUE SALAS YASMY YAMILE ', '2026-08-04 17:38:22.712000', '2026-08-07 13:21:09.839000', NULL, 7, 1, NULL, 'Objetivo General:\nDeterminar el efecto del programa de educación psicomotriz en el neurodesarrollo infantil de los niños de educación inicial de las Islas Flotantes de los Uros expuestos a condiciones de altitud\n\nObjetivos Espécificos;\n- Evaluar el nivel del neurodesarrollo infantil en los niños de educación inicial antes de la aplicación del programa.\n- Aplicar el programa de educación psicomotriz dirigido a niños de educación inicial en condiciones de altitud extrema.\n- Comparar los resultados del neurodesarrollo infantil antes y después de la aplicación del programa', 'NEURODESARROLLO INFANTIL EN CONDICIONES EXTREMAS DE ALTITUD: IMPACTO DEL PROGRAMA DE EDUCACIÓN PSICOMOTRIZ EN NIÑOS DE EDUCACIÓN INICIAL DE LAS ISLAS FLOTANTES DE LOS UROS', 'DOMETILA MAMANI JILAJA', 84.00),
	(322, 'nl8441sxzd6pqeusa5pz2xj4', 'VOCES EN MOVIMIENTO DE TRABAJO SOCIAL', '2026', 'TRABAJO SOCIAL', 'TRABAJO SOCIAL', 10000.00, 'FAMILIAS: REALIDADES, CAMBIO Y DINÁMICAS DE INTERVENCIÓN', 'BUSTINZA VARGAS, JUANA VICTORIA', '2026-08-04 17:39:34.156000', '2026-08-10 03:57:05.703000', NULL, 7, 1, NULL, 'Objetivo General: \nComprender las experiencias comunitarias del desarrollo de bienestar integral construidas por la población del distrito de Cojata frente a la contaminación del río Suches durante el año 2026.\n\nObjetivos Específicos:\nOE1: Comprender las experiencias de vulnerabilidad vividas por la población del distrito de Cojata frente a la contaminación del río Suches.\nOE2: Analizar los procesos de construcción del bienestar integral desarrollados por la población frente a la contaminación del río Suches.', '"EXPERIENCIAS COMUNITARIAS DEL DESARROLLO DE BIENESTAR INTEGRAL ANTE LA CONTAMINACIÓN DEL RÍO SUCHES EN COJATA - 2026"', 'JUANA VICTORIA BUSTINZA VARGAS', 83.83),
	(324, 'jmqr6p1m8j6qv5djpb7dcwo6', 'REDES QUE INSPIRAN EL TURISMO MODERNO', '2026', 'CIENCIAS  SOCIALES', 'TURISMO', 10000.00, 'GESTIÓN DE DESTINOS TURÍSTICOS', 'PAREDES MAMANI, LIZ YOSELYN\nESTEBAN MARCANI, MARGOT YESENIA\nSOTO SANTANA, ERICK MANUEL\nTTITO COAQUIRA, VIVIANA YOLY', '2026-08-04 17:40:02.300000', '2026-08-10 03:55:47.784000', NULL, 7, 1, NULL, 'Obejtivo General:\nEvaluar el efecto de la implementación de WhatsApp Business, como proceso de transferencia de tecnología, en la comercialización del turismo comunitario en comunidades del entorno del Lago Titicaca, región Puno, \n\nObjetivos Específicos:\n1.	Evaluar el efecto de la implementación de WhatsApp Business en el número de consultas turísticas de los emprendimientos de turismo comunitario del entorno del Lago Titicaca.\n2.	Evaluar el efecto de la implementación de WhatsApp Business en el tiempo de respuesta en la atención a los turistas de los emprendimientos de turismo comunitario.\n3.	Evaluar el efecto de la implementación de WhatsApp Business en la captación de clientes de los emprendimientos de turismo comunitario del entorno del Lago Titicaca.\n4.	Evaluar los cambios producidos en los indicadores de comercialización turística después de la implementación de WhatsApp Business como herramienta ', 'TRANSFERENCIA TECNOLÓGICA MEDIANTE EL USO DE WHATSAPP BUSINESS PARA FORTALECER LA COMERCIALIZACIÓN DEL TURISMO COMUNITARIO EN PUNO', 'NOEMI EMPERATRIZ CAYO VELASQUEZ', 83.67),
	(326, 'bf8mdpzz381b7ethrllrjlr5', 'SENSORES 3D - IQ', '2026', 'INGENIERÍA QUÍMICA', 'INGENIERÍA QUÍMICA', 10000.00, NULL, 'CONDORI ARAPA, HAIDER JHAK\nCHAIÑA YANA, LEYDI YUDITH\nRAMOS APAZA, ROSMERY STEFANY\nCHAVEZ MAMANI, CRISTOFHER\nCONDORI MENDOZA, JESÚS RONALDO\nMAMANI GARCÍA, MARÍA', '2026-08-04 17:40:48.202000', '2026-08-10 03:54:36.262000', NULL, 7, 1, NULL, 'Objetivo General:\nDesarrollar y validar sensores electroquímicos impresos en 3D para la determinación de contaminantes emergentes en aguas superficiales de la Bahía Interior del Lago Titicaca.\n\nObejtivos Específicos:\n●	Diseñar y fabricar electrodos conductores mediante impresión 3D FDM. \n●	Activar y caracterizar electroquímicamente los sensores desarrollados. \n●	Optimizar las condiciones analíticas para la detección de contaminantes emergentes. \n●	Evaluar la sensibilidad, precisión y reproducibilidad del sensor. ', 'DESARROLLO DE SENSORES ELECTROQUÍMICOS IMPRESOS EN 3D PARA LA DETERMINACIÓN DE FÁRMACOS Y CONTAMINANTES EMERGENTES DE LA BAHÍA INTERIOR DEL LAGO TITICACA, PUNO', 'TEOFILO DONAIRES FLORES', 82.75),
	(328, 'jgpxq8muu4b0v5p6dapp4sdg', 'ADSOBENTES 3D - IQ', '2026', 'INGENIERÍA QUÍMICA', 'INGENIERÍA QUÍMICA', 10000.00, 'CALIDAD AMBIENTAL', 'GARCIA VILCA, FRANCHESKA NAHOMI\nMAMANI CUNO , GABY JIMENA\nHUANCOLLO CHAMBI , YENI ROSMEDY\nCHURATA MULLISACA , HELEN VANESA\nRAMOS VELÁSQUEZ , ANDRÉ\nVILCA SÁNCHEZ , HELEN GRISEL', '2026-08-04 17:41:27.734000', '2026-08-10 03:53:34.734000', NULL, 7, 1, NULL, 'Objetivo General:\nDesarrollar adsorbentes impresos en 3D modificados con materiales naturales para la remoción de arsénico y plomo en aguas contaminadas del Altiplano peruano.\n\nObjetivos Específicos:\n•	Diseñar estructuras adsorbentes impresas en 3D con diferentes geometrías porosas. \n•	Modificar superficialmente las estructuras utilizando zeolita, biochar, bentonita y óxidos de hierro. \n•	Evaluar la capacidad de adsorción de arsénico y plomo. \n•	Determinar la cinética e isotermas de adsorción. ', 'DESARROLLO DE ADSORBENTES IMPRESOS EN 3D MODIFICADOS CON MATERIALES NATURALES PARA LA REMOCIÓN DE ARSÉNICO Y PLOMO EN AGUAS CONTAMINADAS DEL ALTIPLANO PERUANO', 'TEOFILO DONAIRES FLORES', 82.67),
	(330, 'fwdjz1lh0by9shc2k80fale4', 'ALIMENTOS FUNCIONALES Y NUTRACEÚTICOS EN INVESTIGACIÓN (NUTRIALFA)', '2026', 'INGENIERÍA QUÍMICA', 'INGENIERÍA QUÍMICA', 10000.00, 'PROCESAMIENTO DE ALIMENTOS, FORMULACIÓN, EVALUACIÓN Y GESTIÓN DE PROYECTOS Y EMPRESAS CON ALIMENTOS, NUTRICIÓN Y SALUD, INNOVACIÓN, ANÁLISIS Y CONTROL DE LOS ALIMENTOS EN EL SISTEMA ALIMENTARIO', 'Romero Tisnado, Marcelo Denis\nParhuayo Cornejo , Diego Andre\nQuispe Vidal , Yordan Ronaldho\nCondori Mendoza , Jesús Ronaldo\nJihuallanca Ticona , Lesly Yamileth\nMamani García , María\n', '2026-08-04 17:42:22.496000', '2026-08-10 03:52:23.912000', NULL, 7, 1, NULL, 'Objetivo General:\nElaborar y evaluar nuggets a base de trucha arcoíris (Oncorhynchus mykiss) enriquecidos con harinas de tarwi y quinua como alternativa alimentaria funcional rica en proteínas.\n\nObjetivos Específicos:\n- Formular nuggets de trucha arcoíris con diferentes proporciones de harina de tarwi y harina de quinua.\n- Determinar la composición nutricional de los nuggets elaborados, considerando humedad, proteína, grasa, cenizas, carbohidratos y valor energético.\n- Determinar la calidad microbiológica de los nuggets elaborados para verificar condiciones básicas de inocuidad alimentaria.\n- Evaluar la aceptabilidad sensorial de los nuggets mediante atributos como color, olor, sabor, textura y aceptación general.', 'ELABORACIÓN DE NUGETS A BASE DE TRUCHA ARCOIRIS (ONCORHYCHUS MYKISS) ENRIQUESIDOS CON HARINAS DE TARWI Y QUINUA COMO ALTERNATIVA ALIMENTARIA FUNCIONAL RICA EN PROTEINA', 'EDITH TELLO PALMA', 82.00),
	(332, 'bx0qhsx060ildpw0f9j4ec3t', 'SEMILLERO DE INVESTIGACIÓN PEDAGÓGICA, EDUCATIVA Y SOCIAL WIÑAY (SIPES)', '2026', 'CIENCIAS DE LA EDUCACIÓN', 'EDUCACIÓN PRIMARIA', 10000.00, 'PERSPECTIVAS TEÓRICAS DE LA EDUCACIÓN', 'Pacco Mamani, Flor Gianella\nGonzales Quispe, Maryori Luisa\nCCORI HUANCA, JORGE LUIS\nMamani Salinas , Maria Asunta\nJilaja Salluca , Yunsu Alison\nCHAMBI CALLOHUANCA, Aymee Elida', '2026-08-04 17:43:30.828000', '2026-08-10 03:50:39.929000', NULL, 7, 1, NULL, 'Objetivo General:\nAnalizar la influencia de la ciudadanía digital sobre el uso responsable de la inteligencia artificial a través del pensamiento crítico frente a la IA en estudiantes universitarios.\n\nObjetivos Específicos;\nDeterminar el nivel de ciudadanía digital de los estudiantes universitarios.\nAnalizar la relación entre ciudadanía digital y pensamiento crítico frente a la IA.\nAnalizar la relación entre pensamiento crítico frente a la IA y uso responsable de la IA.\nEvaluar el efecto directo de la ciudadanía digital sobre el uso responsable de la IA.\nEvaluar el efecto mediador del pensamiento crítico frente a la IA.', 'CIUDADANÍA DIGITAL, PENSAMIENTO CRÍTICO Y USO RESPONSABLE DE LA INTELIGENCIA ARTIFICIAL EN ESTUDIANTES UNIVERSITARIOS', 'VIDNAY NOEL VALERO ANCCO', 79.92),
	(334, 'y6f6hba8yi07vtt9ms5w3erg', 'CALIBRATECH PRECISION GROUP', '2026', 'INGENIERÍA  MECÁNICA  ELÉCTRICA, ELECTRÓNICA Y SISTEMAS', 'INGENIERÍA MECÁNICA ELÉCTRICA', 10000.00, 'CONTROL DE PROCESOS', 'HUAHUALA MORA , YAMPIER JOSE\nCUTIPA RAFAEL, CHRISTIAN\nCHURA LLANOS, MARCO ANTONIO\nCUTIPA CHOQUEHUANCA , EDSON', '2026-08-04 17:44:31.747000', '2026-08-10 03:48:53.014000', NULL, 7, 1, NULL, 'Objetivo General:\nDiseñar e implementar un prototipo automatizado para la calibración de detectores de metales en fajas transportadoras, evaluando su desempeño mediante pruebas experimentales\n\nObjetivos Específicos:\nAnalizar el funcionamiento de detectores de metales utilizados en fajas transportadoras mineras.\nDiseñar un sistema electromecánico automatizado para el desplazamiento controlado de patrones metálicos.\nImplementar un sistema de control basado en microcontrolador o PLC para ejecutar rutinas automáticas de calibración.\nEvaluar la precisión y repetibilidad del prototipo mediante pruebas experimentales.', 'DISEÑO E IMPLEMENTACIÓN DE UN PROTOTIPO AUTOMATIZADO PARA LA CALIBRACIÓN DE DETECTORES DE METALES EN FAJAS TRANSPORTADORAS PARA LA INDUSTRIA MINERA.', 'JULIO FREDY CHURA ACERO', 79.75),
	(336, 'n3krh1cxv60uoibegicif0h3', 'COMPOST  TRANSFORMANDO NUESTROS RESIDUOS EN VIDA', '2026', 'CIENCIAS AGRARIAS', 'INGENIERÍA AGRONÓMICA', 10000.00, 'DESARROLLO DE SISTEMAS AGROPECUARIOS', 'MAMANI ARCE, REYNALDO\nMAMANI ITO, KRICELLY JAZMIN\nHUANCA GALLEGOS, YHOMARA YOSELIN PILAR\nTOMA AQUINO, RUIZ VIDAL\nPOMARI HUAYHUA, MIDIAN\nQUISPE CHAMBI, BLANCA NIEVES\n', '2026-08-04 17:45:38.277000', '2026-08-10 03:47:37.370000', NULL, 7, 1, NULL, 'Objetivo General:\nSe evaluará el compostaje aeróbico de residuos universitarios con estiércoles (ovino, vacuno, cuy) enriquecido con Azospirillum brasilense, midiendo su efecto en el proceso, propiedades fisicoquímicas y calidad biofertilizante.\n\nObjetivos Específicos:\nCaracterizar los residuos del comedor y estiércoles (ovino, vacuno, cuy) para formular mezclas estables con humedad del 50% -60% y relación C:N inicial de 25:1 a 30:1.\n\nMonitorear la temperatura y oxigenación en las fases mesófila y termófila ( 55°C) para definir el momento óptimo de inoculación de Azospirillum brasilense en el enfriamiento.\n\nEvaluar las propiedades fisicoquímicas, en concentración de NPK y madurez y viabilidad bacteriana (UFC/g) del compost final, determinando el tratamiento con mejor calidad biofertilizante.', '"OPTIMIZACIÓN DEL PROCESO DE COMPOSTAJE DE RESIDUOS ORGÁNICOS UNIVERSITARIOS MEDIANTE LA INOCULACIÓN DE BACTERIAS PROMOTORAS DEL CRECIMIENTO VEGETAL (BPCP) EN PUNO"', 'RONY ABEL CIPRIAN CARREON', 79.08),
	(338, 'exugui5j6l6fid5k5e1hw2ve', 'DATANOVA LAB', '2026', 'INGENIERÍA ESTADÍSTICA E INFORMÁTICA', 'INGENIERÍA ESTADÍSTICA E INFORMÁTICA', 10000.00, 'ANÁLISIS MULTIVARIADO, BIG DATA, MINERÍA DE DATOS E INVESTIGACIÓN DE MERCADOS', 'YANARICO HUANCA, FLOR MELANY\nLAURA LIVISE, YEFERSON DARIUN\nBUSTINCIO SUAÑA, ANGIE NAHOMI\nGONZÁLES QUISPE, WILFREDO\nPAMPA HUAMAN, WILSON HUGO', '2026-08-04 17:46:37.819000', '2026-08-10 03:46:15.504000', NULL, 7, 1, NULL, 'Objetivo General:\nDesarrollar un modelo predictivo de la producción de quinua en la región de Puno (Perú) basado en la transformada wavelet deformada para la selección óptima de variables agroclimáticas y la \n\nObjetivos Específicos:\n1. Recopilar y sistematizar datos históricos de producción de quinua y variables agroclimáticas (temperatura, precipitación, humedad, radiación solar) en la región de Puno para el período de análisis definido.\n\n2. Aplicar el método de selección de características mediante wavelets deformadas para identificar las variables agroclimáticas más influyentes en la producción de quinua con alta probabilidad.\n\n3. Ajustar modelos de regresión no paramétrica (regresión kernel local y B-splines) con las variables seleccionadas para estimar la producción de quinua.\n\n4. Evaluar y comparar el desempeño predictivo del modelo propuesto frente a métodos de regresión clásica mediante métricas estadísticas apropiadas.\n', 'PREVISIÓN DE LA PRODUCCIÓN DE QUINUA EN PUNO (PERÚ), BASADA EN LA TRANSFORMADA WAVELET, CONSIDERANDO VARIABLES AGROCLIMÁTICAS', 'GODOFREDO QUISPE MAMANI', 78.00),
	(340, 'ufznnmmoekkvtma0zmv1swcj', 'GRUPO PENSAMIENTO CRÍTICO ANTROPOLÓGICO UNA-PUNO', '2026', 'CIENCIAS  SOCIALES', 'ANTROPOLOGÍA', 10000.00, 'SOCIOLINGÜÍSTICA E INTERCULTURALIDAD', 'LUPACA VILCA CARMEN ROSA\nCCAMA LIMA NANCY MARIA LUISA\nLUJANO RAMOS YESLIT DAYANA\nCONDORI TICONA CRISTHIAN DANIEL\nINCACUTIPA INCACUTIPA LEONARDO\nSOSA MAMANI ABEL GIOARVY\n', '2026-08-04 17:47:13.723000', '2026-08-07 13:16:16.531000', NULL, 7, 1, NULL, 'Objetivo General:\nIdentificar los significados que las comunidades rurales aymaras del sur peruano atribuyen a la democracia a partir de las vivencias con las instituciones democráticas del Estado.\n\nObjetivos Específicos:\n- Describir las concepciones de la democracia presentes en las comunidades rurales aymaras.\n- Analizar las formas de participación política y toma de decisiones desarrolladas en las comunidades aymaras del altiplano peruano\n- Identificar las percepciones de los comuneros aymaras respecto a la representación política y las instituciones estatales.', '“EL SIGNIFICADO DE LA DEMOCRACIA PARA LAS COMUNIDADES RURALES AYMARAS EN EL PERÚ”', 'VICENTE ALANOCA AROCUTIPA', 77.83),
	(385, 'p7jsx01jhxlbvxc7hi76u9o1', 'ARS BAYESIANA', '2026', 'INGENIERÍA ESTADÍSTICA E INFORMÁTICA', 'INGENIERÍA ESTADÍSTICA E INFORMÁTICA', 10000.00, 'MODELOS PREDICTIVOS UNI Y MULTIVARIANTES, INTELIGENCIA ARTIFICIAL, SISTEMAS COMPUTACIONALES Y SISTEMAS BIOINSPIRADOS', 'QUISPE QUISPE RONALDO EDDSON\nQUISPE CALATAYUD NELIDA ARACELY\nCHILI LIMA ANDRE\'E ALESSANDRO\n', '2026-08-04 17:14:11.139000', '2026-08-07 13:11:37.191000', '2026-08-07 13:11:37.211000', 7, 1, NULL, 'Objetivo General:\nDeterminar la relación entre la adicción a redes sociales, el estilo de vida y la salud mental en estudiantes de la Universidad Nacional del Altiplano Puno, mediante redes bayesianas\n\nObjetivos Específicos:\n• Describir los niveles de adicción a redes sociales, estilo de vida y salud mental en la muestra de estudiantes universitarios.\n• Determinar la relación entre adicción a redes sociales y salud mental en estudiantes universitarios.\n• Determinar la relación entre adicción a redes sociales y estilos de vida en estudiantes universitarios.\n• Aplicar un modelo de redes bayesianas para identificar la estructura causal conjunta entre la adicción a redes sociales, el estilo de vida y la salud mental en estudiantes de la Universidad Nacional del Altiplano Puno', 'ADICCIÓN A REDES SOCIALES Y SU RELACIÓN CON EL ESTILO DE VIDA Y LA SALUD MENTAL EN ESTUDIANTES DE LA UNIVERSIDAD NACIONAL DEL ALTIPLANO PUNO: UN MODELO DE  REDES BAYESIANAS', 'ANGEL JAVIER QUISPE CARITA', 89.42),
	(386, 'ijwl73psgro8351y72wubmwo', 'SEMILLERO"GENERACCIONSOCIAL', '2026', 'TRABAJO SOCIAL', 'TRABAJO SOCIAL', 10000.00, 'DERECHOS HUMANOS Y FORTALECIMIENTO DEMOCRÁTICO', 'Balcona Chambilla Lorena Britney\nBLANCO MEZA LEONOR NICOLE\nCOILA CHOQUE SIDNEY YANIRA\nESQUERRE YANA JUAN ANTHONY\nJALLO HUANCAVILCA MILAGROS YOSY\nUMIÑA NUÑEZ MAYTE LORENA\n', '2026-08-04 17:25:45.254000', '2026-08-07 13:12:09.433000', '2026-08-07 13:12:09.448000', 7, 1, NULL, 'Objetivo General:\nDeterminar la relación entre la gobernanza algorítmica y las brechas de acceso a servicios públicos digitales en los pobladores del Centro Poblado Menor de Llachón, distrito de Capachica, Puno, 2026.\n\nObjetivos Específicos:\n- Identificar la relación entre la legitimidad de entrada de la  algorítmica y las brechas de acceso a servicios públicos digitales en los pobladores del Centro Poblado Menor de Llachón,\n- Describir la relación entre la legitimidad del proceso de la gobernanza algorítmica y las brechas de acceso a servicios públicos digitales en los pobladores\n-Establecer la relación entre la legitimidad de los resultados de la gobernanza algorítmica y las brechas de acceso a servicios públicos digitales en los pobladores', 'GOBERNANZA ALGORÍTMICA Y BRECHAS DE ACCESO A SERVICIOS PÚBLICOS DIGITALES EN POBLADORES DEL CENTRO POBLADO MENOR DE LLACHÓN, CAPACHICA, PUNO, 2026.', 'SOLEDAD JACKELINE ZEGARRA UGARTE', 87.50),
	(387, 'p3cqkyt51x1m7g90h352r9xs', '“SEMILLERO DE INVESTIGACIÓN EN DISEÑO DE MATRICES ALIMENTARIAS FUNCIONALES (SI- DMAF)”', '2026', 'CIENCIAS AGRARIAS', 'INGENIERÍA AGROINDUSTRIAL', 10000.00, 'INGENIERÍA, TECNOLOGÍA Y GESTIÓN AGROINDUSTRIAL, PROCESAMIENTO DE ALIMENTOS', 'Lira Pinazo Paola Rosario\nTorres Vargas Dana Cielo\nYucra Callamullo Yakelin\nYucra López Samuel Valentín\n', '2026-08-04 17:25:10.731000', '2026-08-07 13:12:46.198000', '2026-08-07 13:12:46.219000', 7, 1, NULL, 'Objetivo General:\nDesarrollar un ingrediente funcional en polvo a partir de fresas de altura mediante un sistema híbrido de secado por ventana de refractancia y microondas, evaluando su influencia sobre sus propiedades.\n\nObjetivos Específicos:\nDeterminar el efecto de la temperatura y tiempo de secado por ventana de refractancia y de la potencia de microondas, sobre las características de deshidratación de las fresas de altura.\nEvaluar las propiedades fisicoquímicas del ingrediente funcional en polvo obtenido mediante un sistema híbrido de secado por ventana de refractancia y microondas.\nAnalizar las propiedades físicas y colorimétricas del ingrediente funcional en polvo obtenido a partir de fresas de altura mediante un sistema híbrido de secado por ventana\nCuantificar la retención de vitamina C, compuestos fenólicos totales, antocianinas y capacidad antioxidante del ingrediente funcional en polvo obtenido.', '“VALORIZACIÓN DE FRESAS (FRAGARIA × ANANASSA) DE ALTURA MEDIANTE LA OBTENCIÓN DE UN INGREDIENTE FUNCIONAL EN POLVO UTILIZANDO UN SISTEMA HÍBRIDO DE SECADO POR VENTANA"', 'WENCESLAO TEDDY MEDINA ESPINOZA', 87.50),
	(388, 'jhb9r52g351nxmcd4vbxew0v', 'SEMILLERO DE INVESTIGACIÓN, INNOVACIÓN Y UNIÓN SOCIAL” (SIRIUS)', '2026', 'TRABAJO SOCIAL', 'TRABAJO SOCIAL', 10000.00, 'DESARROLLO HUMANO Y CALIDAD DE VIDA', 'MAMANI FLORES YÓMELY NAZIRA\nMAMANI TORRES BEATRIZ\nTURPO MAMANI FIORELA MAGALY\n', '2026-08-04 17:24:41.356000', '2026-08-07 13:13:13.815000', '2026-08-07 13:13:13.839000', 7, 1, NULL, 'Objetivo General:\nAnalizar la relación entre los entornos digitales y el bienestar socioemocional de los estudiantes de educación secundaria de las instituciones educativas GUE San Carlos e IES Carlos Rubina Burgos\n\nObjetivos Específicos:\n• Identificar los patrones de uso de entornos digitales (redes sociales y plataformas digitales) de los estudiantes de educación secundaria de la ciudad de Puno.\n• Describir el nivel de bienestar socioemocional, considerando los indicadores de ansiedad, depresión y autoestima, en los estudiantes de educación secundaria de la ciudad de Puno.\n• Determinar el grado de relación entre el uso de entornos digitales y el bienestar socioemocional (ansiedad, depresión y autoestima) de los estudiantes de educación secundaria de la ciudad de Puno.\n• Proponer lineamientos de orientación socioeducativa que favorezcan una relación saludable entre los estudiantes y los entornos digitales\n', 'ENTORNOS DIGITALES Y BIENESTAR SOCIOEMOCIONAL: UN ESTUDIO SOBRE LA SALUD MENTAL EN ESTUDIANTES DE SECUNDARIA DE LA CIUDAD DE PUNO', 'ZEZY YADEYDA SARDON ARI', 87.58),
	(389, 'z89z1brfurealxlgy3vdfqyt', 'RAICES HUMANAS', '2026', 'CIENCIAS  SOCIALES', 'ANTROPOLOGÍA', 10000.00, 'CULTURA ANDINA, SOCIEDAD Y MEDIOAMBIENTE', 'SUAÑA FLORES CRISTHIAN\nMIRANDA TINTA ALEXANDER\nDIAZ CUTIPA ROXANA NILVIA\nZAPANA PEREZ KAREN GABRIELA\nTITO CCAPA JESSICA ROSSY\nCALIZAYA BALCONA LIBERTAD NAYESKA', '2026-08-04 17:24:14.869000', '2026-08-07 13:13:46.226000', '2026-08-07 13:13:46.241000', 7, 1, NULL, 'Objetivo General:\nAnalizar las transformaciones de la cultura alimentaria andina en términos de prácticas, significados e influencias contemporáneas, en la alimentación de los estudiantes de Antropología de la Universidad Nacional del Altiplano\n\nObjetivos Específicos:\n- Identificar las prácticas alimentarias predominantes en los estudiantes de Antropología.\n- Interpretar los significados culturales que los estudiantes atribuyen a la alimentación tradicional y moderna.\n- Examinar las influencias contemporáneas que inciden en las prácticas alimentarias de los estudiantes.\n- Analizar la relación entre prácticas alimentarias y significados culturales en el contexto de transformación alimentaria.', 'TRANSFORMACIONES DE LA CULTURA ALIMENTARIA ANDINA: PRÁCTICAS, SIGNIFICADOS E INFLUENCIAS CONTEMPORÁNEAS EN LA ALIMENTACIÓN DE ESTUDIANTES DE ANTROPOLOGÍA DE LA UNIVERSIDAD NACIONAL DEL ALTIPLANO PUNO', 'DAVID ELEAZAR BARRA QUISPE', 87.53),
	(390, 'se05ym58f90djl8o7dfbng65', 'SEMILLERO DE INVESTIGACIÓN ETNOMATEMÁTICA Y SABERES ANDINOS (SIESA)', '2026', 'CIENCIAS DE LA EDUCACIÓN', 'EDUCACIÓN SECUNDARIA', 10000.00, 'INTERDISCIPLINARIEDAD EN LA DINÁMICA EDUCATIVA: TEORÍA Y MÉTODOS DE INVESTIGACIÓN DE LA DIDÁCTICA DE LA MATEMÁTICA', 'Chura Humora Edgar\nApaza Umpire Jackeline\nCondori Paricahua Ximena Aracely\n', '2026-08-04 17:21:01.075000', '2026-08-07 13:14:18.780000', '2026-08-07 13:14:18.794000', 7, 1, NULL, 'Objetivo General:\nAnalizar las nociones de probabilidad presentes en la lectura de la hoja de coca practicada por los yatiris del altiplano puneño desde una perspectiva etnomatemática.\n\nObjetivos Específicos:\n− Describir las etapas, procedimientos y significados culturales que intervienen en la lectura de la hoja de coca practicada por los yatiris.\n− Identificar formas de razonamiento vinculadas a la incertidumbre, la valoración de posibilidades y la interpretación de acontecimientos futuros presentes en la práctica ritual.\n− Analizar las nociones probabilísticas implícitas que emergen durante los procesos de interpretación desarrollados por los yatiris.\n− Interpretar los hallazgos identificados a partir de los fundamentos teóricos del Programa Etnomatemática.', 'NOCIONES DE PROBABILIDAD EN LA LECTURA DE LA HOJA DE COCA: UN ESTUDIO ETNOMATEMÁTICO CON YATIRIS DEL ALTIPLANO PUNEÑO', 'BETHZABE COTRADO MENDOZA', 88.25),
	(391, 'p0n8z9li6sme8c34j87q62n8', 'ESENCIA ALTIPLÁNICA', '2026', 'CIENCIAS AGRARIAS', 'INGENIERÍA AGROINDUSTRIAL', 10000.00, 'RECUPERACIÓN, CONSERVACIÓN Y TRANSFORMACIÓN DE RECURSOS NATURALES, INGENIERÍA, TECNOLOGÍA Y GESTIÓN AGROINDUSTRIAL', 'NAIRA APAZA RUTH THANIA\nCCOA CCOA NAYDA YULISA\nCCACCA APAZA FLOR GIMENA', '2026-08-04 17:18:42.825000', '2026-08-07 13:14:40.324000', '2026-08-07 13:14:40.340000', 7, 1, NULL, 'Objetivo General: \nDesarrollar una crema fotoprotectora con actividad antioxidante y antiinflamatoria a partir de cushuro y saponinas de quinua\n\nObjetivos Específicos:\n1. Comparar los métodos de maceración hidroetanólica y extracción asistida por microondas para la obtención de extractos antioxidantes de cushuro (Nostoc sphaericum).\n2. Extracción de saponinas de quinua con disolventes eutécticos profundos de cascaras de tres variedades de quinua nativa\n3. Evaluar la actividad antioxidante y antiinflamatoria de formulaciones de crema fotoprotectora con adición de extracto de cushuro y saponinas de quinua', 'DESARROLLO DE UNA CREMA FOTOPROTECTORA CON ACTIVIDAD ANTIOXIDANTE Y ANTIINFLAMATORIA A PARTIR DE CUSHURO Y SAPONINAS DE QUINUA', 'MARIANELA CALSIN CUTIMBO', 88.58),
	(392, 'xl9bzk0d8nbm9yud14up6usv', 'INNOVACIÓN EDUCATIVA', '2026', 'CIENCIAS DE LA EDUCACIÓN', 'EDUCACIÓN SECUNDARIA', 10000.00, 'INNOVACIÓN EDUCATIVA Y PRACTICAS PEDAGÓGICAS, DESARROLLO DEL PROCESO PEDAGÓGICO', 'Mamani Quispe Sorayma Sandra\nMachaca Condori Flora Miriam \nLopez Ramos Dino Becker\nNuñez Condori Brainer Jeferson\nCcari Mamani Dante Elmer\nQuispe Morocco Jeidy Zenaida\n', '2026-08-04 17:17:38.549000', '2026-08-07 13:15:04.711000', '2026-08-07 13:15:04.724000', 7, 1, NULL, 'Objetivos General: \nDeterminar la contribución de la pedagogía basada en el juego al desarrollo del saber ser en estudiantes del Programa de Lengua, Literatura y Psicología de la Universidad Nacional del Altiplano\n\nObjetivos Específicos:\n1. Diagnosticar el nivel de desarrollo del saber ser en los estudiantes antes de la aplicación de la pedagogía basada en el juego.\n2. Evaluar el nivel de desarrollo del saber ser en los estudiantes después de la aplicación de la pedagogía basada en el juego.\n3. Determinar la contribución de la pedagogía basada en el juego al desarrollo del saber ser mediante la comparación de los resultados obtenidos antes y después de la intervención.', 'LA PEDAGOGÍA BASADA EN EL JUEGO PARA EL DESARROLLO DEL SABER SER EN ESTUDIANTES DEL PROGRAMA DE LENGUA, LITERATURA Y PSICOLOGÍA', 'SILVIA VERONICA VALDIVIA YABAR', 85.58),
	(393, 'h2to2i4k6dauyl4akie0bjy6', 'SOCIOLOGÍA PARA LA INVESTIGACIÓN ACCIÓN - SOCIOLOGIA', '2026', 'CIENCIAS  SOCIALES', 'SOCIOLOGÍA', 10000.00, 'ECONOMÍA REGIONAL Y LOCAL, DESARROLLO HUMANO Y CALIDAD DE VIDA, PROCESAMIENTO DE ALIMENTOS', 'Jallo Yucra Edwin \nChoquemamani Luque Royer\nLuque Luque Grover Rudy\nCcallo Condori Cristhian Jhoner\nVasquez Sandoval Zenaida Yesica\nHuanca Velasquez Pilar\n', '2026-08-04 17:17:01.817000', '2026-08-07 13:15:33.526000', '2026-08-07 13:15:33.545000', 7, 1, NULL, 'Objetivo General:\nDeterminar la relación entre el capital social y las prácticas de innovación en la producción de derivados lácteos en productores rurales de comunidades ubicadas en los distritos de Huata y\n\nObjetivos Específicos:\nDeterminar la relación entre la estructura y el alcance de las redes sociales y las prácticas de innovación en la producción de derivados lácteos en productores rurales de comunidades ubicadas en los distritos de Huata y Acora, Puno.\nDeterminar la relación entre los niveles de confianza social y las prácticas de innovación en la producción de derivados lácteos en productores rurales de comunidades ubicadas en los distritos de Huata y Acora, Puno.\nDeterminar la relación entre las prácticas de reciprocidad y cooperación y las prácticas de innovación en la producción de derivados lácteos en productores rurales de comunidades ubicadas en\n', 'CAPITAL SOCIAL Y PRÁCTICAS DE INNOVACIÓN EN LA PRODUCCIÓN DE DERIVADOS LÁCTEOS DE PRODUCTORES RURALES EN EL DISTRITO DE HUATA Y ACORA, PUNO', 'GUSTAVO MEDINA VILCA', 89.08),
	(394, 'tj4qcbm9cza5mbrovtfvr8ei', 'SEMILLERO DE INVESTIGACIÓN EDUCATIVA YACHAY', '2026', 'CIENCIAS DE LA EDUCACIÓN', 'EDUCACIÓN PRIMARIA', 10000.00, 'PERSPECTIVAS TEÓRICAS DE LA EDUCACIÓN', 'VALERO ANCCO VIDNAY NOEL\nROJAS CASTRO DIANA LIZET \nMACHACA CASTRO YANETH MARIBEL \nRojas Castro Manuel Enrique\nCalcina Quispe Luz Estrella\nCenteno Lipa Feli Isabel \nCaxi Cahui Xiomara María ', '2026-08-04 17:15:48.645000', '2026-08-07 13:15:56.350000', '2026-08-07 13:15:56.363000', 7, 1, NULL, 'Objetivo General:\nAnalizar el nivel de alfabetización en inteligencia artificial y su relación con la competencia digital, el pensamiento crítico y el uso responsable de la IA en estudiantes universitarios\n\nObjetivos Específicos:\nIdentificar el nivel de alfabetización en inteligencia artificial en estudiantes universitarios.\nDescribir los niveles de competencia digital, pensamiento crítico y uso responsable de la IA en estudiantes universitarios.\nAnalizar la relación entre la alfabetización en inteligencia artificial, la competencia digital, el pensamiento crítico y el uso responsable de la IA.', 'COMPETENCIA DIGITAL, PENSAMIENTO CRÍTICO Y ALFABETIZACIÓN EN INTELIGENCIA ARTIFICIAL EN ESTUDIANTES UNIVERSITARIOS', 'VIDNAY NOEL VALERO ANCCO', 89.25),
	(395, 'ufznnmmoekkvtma0zmv1swcj', 'GRUPO PENSAMIENTO CRÍTICO ANTROPOLÓGICO UNA-PUNO', '2026', 'CIENCIAS  SOCIALES', 'ANTROPOLOGÍA', 10000.00, 'SOCIOLINGÜÍSTICA E INTERCULTURALIDAD', 'LUPACA VILCA CARMEN ROSA\nCCAMA LIMA NANCY MARIA LUISA\nLUJANO RAMOS YESLIT DAYANA\nCONDORI TICONA CRISTHIAN DANIEL\nINCACUTIPA INCACUTIPA LEONARDO\nSOSA MAMANI ABEL GIOARVY\n', '2026-08-04 17:47:13.723000', '2026-08-07 13:16:16.531000', '2026-08-07 13:16:16.545000', 7, 1, NULL, 'Objetivo General:\nIdentificar los significados que las comunidades rurales aymaras del sur peruano atribuyen a la democracia a partir de las vivencias con las instituciones democráticas del Estado.\n\nObjetivos Específicos:\n- Describir las concepciones de la democracia presentes en las comunidades rurales aymaras.\n- Analizar las formas de participación política y toma de decisiones desarrolladas en las comunidades aymaras del altiplano peruano\n- Identificar las percepciones de los comuneros aymaras respecto a la representación política y las instituciones estatales.', '“EL SIGNIFICADO DE LA DEMOCRACIA PARA LAS COMUNIDADES RURALES AYMARAS EN EL PERÚ”', 'VICENTE ALANOCA AROCUTIPA', 77.83),
	(396, 'zzq7lijj79zpogg9hwoyk5xj', 'TRANSFORMANDO LA ALIMENTACIÓN EN PRODUCCIÓN', '2026', 'CIENCIAS AGRARIAS', 'INGENIERÍA AGRONÓMICA', 10000.00, 'DESARROLLO DE SISTEMAS AGROPECUARIOS', 'FLORES FLORES YOSHYA ELIDA\nAPAZA ZELA ELVIS JHASIEL\nPAMPA CHAMBI HUBER ROLANDO\nDIAZ COILA NILBER EDWIN\nAMBROSIO MULLISACA DENILSON SUMI\nONOFRE CACHICATARI EVER POOL\nCHURA CALCINA YESSICA\n\n\n', '2026-08-04 17:13:46.596000', '2026-08-07 13:16:47.953000', '2026-08-07 13:16:47.965000', 7, 1, NULL, 'Objetivo General:\nMaximizar la producción y calidad de la leche mediante la optimización energética de la ración, mitigando el balance energético negativo en vacas lecheras durante la época seca en el Centro\n\nObjetivos Específicos:\nEvaluar el consumo de materia seca voluntario y la conversión alimenticia de las vacas lecheras sometidas a los diferentes tratamientos energéticos y niveles de fibra.\nCuantificar el volumen diario de leche producida y la ganancia de peso corporal al inicio y al final del periodo experimental para determinar el rendimiento productivo.\nAnalizar la calidad físico-química y composicional de la leche obtenida en cada ordeño en función de la densidad energética y el porcentaje de fibra suministrado.\nDeterminar la ración óptima que mitigue el balance energético negativo (BEN), asegurando la viabilidad económica y metabólica del hato durante la época de estiaje', 'NUTRICIÓN DE PRECISIÓN ENERGÉTICA EN VACAS LECHERAS: ESTRATEGIA PARA CONTROLAR EL BALANCE ENERGÉTICO NEGATIVO DURANTE LA ÉPOCA SECA', 'RONY ABEL CIPRIAN CARREON', 89.83),
	(397, 'hbpt2pdi164luy3ifuqby4g7', 'ORAL HEALTH RESEARCHERS TEAM (OHRT)', '2026', 'CIENCIAS DE LA SALUD', 'ODONTOLOGÍA', 10000.00, 'SALUD PÚBLICA, CIENCIAS MEDICAS BÁSICAS', 'Tintaya Quispe Evelyn Lizzet\nQuispe Apaza Marco Arnold\nJamachi Ccama Franz Alexis\nAguilar Huanca José Miguel\nCallasaca Tacar Yamilet Gleny\n\n\n', '2026-08-04 17:11:24.721000', '2026-08-07 13:17:16.174000', '2026-08-07 13:17:16.188000', 7, 1, NULL, 'Objetivo General:\nEvaluar la actividad antimicrobiana y antifúngica de enjuagues bucales de Minthostachys mollis y Eucalyptus globulus frente a cepas certificadas y aislamientos clínicos orales.\n\nObjetivos Específicos:\n- Determinar la actividad antimicrobiana frente a Streptococcus mutans.\n- Determinar la actividad antimicrobiana frente a Lactobacillus spp.\n- Determinar la actividad antifúngica frente a Candida albicans.\n- Comparar la actividad de las formulaciones hidroalcohólica y de aceites esenciales frente a los microorganismos evaluados\n- Comparar la susceptibilidad de cepas certificadas y aislamientos clínicos frente a las formulaciones de enjuague bucal artesanal evaluadas.\n- Comparar la actividad antimicrobiana y antigungica de las formulaciones respecto al control positivo de Clorhexidina al 0,12 %', 'ACTIVIDAD ANTIMICROBIANA Y ANTIFÚNGICA DE ENJUAGUES BUCALES A BASE DE MINTHOSTACHYS MOLLIS Y EUCALYPTUS GLOBULUS FRENTE A CEPAS CERTIFICADAS Y AISLAMIENTOS CLÍNICOS ORALES DE ESCOLARES ', 'VILMA MAMANI CORI', 91.25),
	(398, 'jdli9ycchtakhp8vpydli948', 'SINERGIA ODONTO-KIDS', '2026', 'CIENCIAS DE LA SALUD', 'ODONTOLOGÍA', 10000.00, 'SALUD DEL RECIÉN NACIDO, NIÑO, ESCOLAR Y ADOLESCENTE', 'Carhuamaca Trujillano Ariana Rachel\nFlores Ccaccallaca Luis Fernando \nTapia Choque Stephany Edith\nAyna Jaliri Leonela Alexandra\nTito Mamani Brayan Steven\n', '2026-08-04 17:10:41.072000', '2026-08-07 13:17:40.540000', '2026-08-07 13:17:40.557000', 7, 1, NULL, 'Objetivo General:\nDeterminar la efectividad de una intervención preventiva estratificada según riesgo de caries sobre la evolución de lesiones iniciales de caries en escolares de la I.E.P. N.° 70035 Bellavista, Puno, 2026.\n\nObjetivos Específicos:\n- Comparar la proporción de lesiones iniciales de caries (ICDAS 1 y 2) que presentan remineralización, estabilidad o progresión entre los grupos.\n- Comparar la evolución de las lesiones iniciales de caries según el nivel de riesgo de caries en los escolares participantes\n- Comparar el número promedio de lesiones iniciales de caries por escolar entre los grupos.\n- Comparar el índice de placa bacteriana de Silness y Löe entre los grupos.\n- Comparar los cambios en los hábitos de higiene oral entre los grupos.\n- Comparar los cambios en los conocimientos sobre salud bucal entre los grupos.\n', 'EFECTIVIDAD DE UNA INTERVENCIÓN PREVENTIVA ESTRATIFICADA SEGÚN RIESGO DE CARIES SOBRE LESIONES INICIALES DE CARIES EN ESCOLARES DE LA I.E.P. N.° 70035 BELLAVISTA, PUNO, 2026.', 'VILMA MAMANI CORI', 91.42),
	(399, 'yriu24q9dwie032uas1mns24', 'COMPUGRAPH PUNO', '2026', 'INGENIERÍA MECÁNICA ELÉCTRICA, ELECTRÓNICA Y SISTEMAS', 'INGENIERÍA DE SISTEMAS', 10000.00, 'INTELIGENCIA ARTIFICIAL, SISTEMAS COMPUTACIONALES Y SISTEMAS BIOINSPIRADOS', 'Rojas Luque Franco\nMendoza Macedo José Miguel\nCondori Nina Mildward Erik\nAguilar Anccori Jhon Elias\n\n', '2026-08-04 17:10:10.342000', '2026-08-07 13:18:00.718000', '2026-08-07 13:18:00.732000', 7, 1, NULL, 'Objetivo General:\nDesarrollar y validar ANDES-DT, gemelo digital neural con U-Net, Chronos-2 y OpenGL 3.3+ para simular el cambio climático en la ribera del Titicaca.\n\nObjetivos Específicos:\nOE1. Curar el dataset multimodal con Sentinel-2 L2A (2018-2025), SRTM, ERA5 y nivel lacustre SENAMHI.\nOE2. Entrenar el U-Net para segmentación de seis clases sobre chips Sentinel-2 de 256×256 px.\nOE3. Ajustar Chronos-2 y proyectar escenarios SSP2-4.5 y SSP5-8.5 para 2030, 2050 y 2080.\nOE4. Desarrollar la visualización 3D en OpenGL 3.3+ con malla DEM, Phong y timeline.\nOE5. Validar con PSNR, SSIM, LPIPS e IoU sobre el holdout 2023-2025, ANOVA α = 0.05.', 'ANDES-DT: GEMELO DIGITAL NEURAL CON INTELIGENCIA ARTIFICIAL GENERATIVA Y MODELOS DE DIFUSIÓN PARA LA SIMULACIÓN PREDICTIVA 4D DEL CAMBIO CLIMÁTICO EN EL ALTIPLANO PERUANO', 'HUGO YOSEF GOMEZ QUISPE', 91.50),
	(400, 'kpvcjcvmv2hrb3fyv9wiriet', 'SEMILLERO DE INVESTIGACIÓN TECNOLÓGICA Y EDUCACIÓN INCLUSIVA – “AXIS”', '2026', 'INGENIERÍA MECÁNICA ELÉCTRICA, ELECTRÓNICA Y SISTEMAS', 'INGENIERÍA DE SISTEMAS', 10000.00, 'INGENIERÍA DE SOFTWARE, BASES DE DATOS E INTELIGENCIA DE NEGOCIOS', 'VARGAS URPI ALBINO\nMONROY QUISPE MARICARMEN\nLLANOS TICONA BLANCA ROSARIO\nRAMOS VILCA FRANCY JIMENA\nFLORES FLORES EMERSON ALDAIR\nSUAÑA HANCCO GUIDO\n\n', '2026-08-04 17:09:30.228000', '2026-08-07 13:18:32.135000', '2026-08-07 13:18:32.151000', 7, 1, NULL, 'Objetivo General:\nDiseñar y validar un software con inteligencia artificial para mejorar el tamizaje no invasivo de anemia infantil en Puno, usando imágenes multimodales y corrigiendo la hemoglobina por altitud.\n\nObjetivos Específicos:\nDiseñar la arquitectura modular del sistema para la gestión de datos e inferencia; construir un dataset local anonimizado con imágenes de conjuntiva, palma y lecho ungueal vinculadas a la altitud y hemoglobina de referencia; entrenar y comparar modelos de IA unimodales y multimodales para clasificar la anemia mediante smartphones; analizar el impacto de la corrección altitudinal en el rendimiento del modelo contrastando sus métricas diagnósticas; y desarrollar un prototipo Android offline, evaluando su usabilidad y concordancia mediante una prueba piloto controlada.', 'SISTEMA DE SOFTWARE CON INTELIGENCIA ARTIFICIAL PARA TAMIZAJE NO INVASIVO DE ANEMIA INFANTIL EN POBLACIONES ALTOANDINAS DE PUNO ', 'ALDO HERNAN ZANABRIA GALVEZ', 93.08),
	(401, 'hye7uhfelyl5dx4gf4qbfoce', 'AGROIDET', '2026', 'CIENCIAS AGRARIAS', 'INGENIERÍA AGROINDUSTRIAL', 10000.00, 'INGENIERÍA, TECNOLOGÍA Y GESTIÓN AGROINDUSTRIAL', 'CORNEJO PINTO ANDRES LADISLAO\nMAMANI ARIVILCA YENY ISAURA\nMERMA QUISPE NOHEMY\nCONDORI HUARACHI WILLY ABDEL\nORDOÑEZ ZEA ANEL MAYELI\nUMIÑA MACHACA LEYDI LAURA\n', '2026-08-04 17:07:28.361000', '2026-08-07 13:18:56.890000', '2026-08-07 13:18:56.907000', 7, 1, NULL, 'Objetivo General:\nDesarrollar sistema CNN que detecte y clasifique plagas/anomalías en quinua y cañihua, usando imágenes de celular, para apoyar diagnóstico fitosanitario a productores de Puno.\n\nObjetivos Específicos:\nOE1. Construir un dataset de imágenes de quinua y cañihua con categorías de plagas y anomalías representativas del altiplano puneño.\nOE2. Entrenar y optimizar modelos CNN (MobileNetV2 y ResNet-50) mediante transferencia de aprendizaje para la clasificación de plagas y anomalías en los cultivos objetivo.\nOE3. Implementar una herramienta interactiva en que integre el modelo CNN para diagnóstico en tiempo real con recomendaciones de tratamiento fitosanitario', 'SISTEMA DE DETECCIÓN Y CLASIFICACIÓN DE PLAGAS Y ANOMALÍAS EN QUINUA Y CAÑIHUA MEDIANTE REDES NEURONALES CONVOLUCIONALES (CNN) ', 'RONALD ASTETE TEBES', 93.17),
	(402, 'bgpq4ikyo1oudqwd0r8ulvm8', 'INNOVA SISTEMAS', '2026', 'INGENIERÍA MECÁNICA ELÉCTRICA, ELECTRÓNICA Y SISTEMAS', 'INGENIERÍA DE SISTEMAS', 10000.00, 'INGENIERÍA DE SOFTWARE, BASES DE DATOS E INTELIGENCIA DE NEGOCIOS, INTELIGENCIA ARTIFICIAL, SISTEMAS COMPUTACIONALES Y SISTEMAS BIOINSPIRADOS', 'ANCO COAQUIRA JORGE LUIS\nQUISPE BRAVO EDER ANDER\nPOMA MAQUERA ABAD\nDELGADO JIMENEZ MARIO SAUL\nMACHACA CAHUANA GIANMARCO ALAIN BRUNO\nARISACA TORRES MARK GREGORY\n\n', '2026-08-04 17:06:50.253000', '2026-08-07 13:19:30.937000', '2026-08-07 13:19:30.958000', 7, 1, NULL, 'Objetivo General:\nDesarrollar un sistema de detección temprana y alerta de conflictos socioambientales y políticos en Puno mediante procesamiento de lenguaje natural y agentes de inteligencia artificial en n8n.\n\nObjetivos Específicos:\nSeleccionar y caracterizar las fuentes de información digital y APIs de datos públicos locales, evaluando su nivel de confiabilidad para el monitoreo de señales de descontento.\nDiseñar la arquitectura de software orientada a eventos y el sistema de roles secuenciales para el Sistema Multiagente (MAS) integrado como middleware en n8n.\nImplementar flujos automatizados en n8n para la extracción, preprocesamiento y canalización asíncrona datos mediante APIs.\nDesarrollar e integrar los agentes PLN para filtrar e identificar indicadores críticos de conflicto.\nEvaluar experimentalmente la precisión y el tiempo de respuesta del sistema automatizado utilizando el corpus de validación.\n', 'SISTEMA DE DETECCIÓN TEMPRANA DE CONFLICTOS SOCIOAMBIENTALES Y POLÍTICOS EN PUNO MEDIANTE PROCESAMIENTO DE LENGUAJE NATURAL Y UNA ARQUITECTURA BASADA EN AGENTES DE INTELIGENCIA ARTIFICIAL.', 'ALDO HERNAN ZANABRIA GALVEZ', 93.67),
	(403, 'jfl26mw9rru0fz2k2b40gcm8', 'GEOFFREY HINTON - IIICCD', '2026', 'INGENIERÍA ESTADÍSTICA E INFORMÁTICA', 'INGENIERÍA ESTADÍSTICA E INFORMÁTICA', 10000.00, 'MODELOS PREDICTIVOS UNI Y MULTIVARIANTES, INGENIERÍA DE SOFTWARE E INTELIGENCIA ARTIFICIAL, ANÁLISIS MULTIVARIADO, BIG DATA, MINERÍA DE DATOS E INVESTIGACIÓN DE MERCADOS', 'QUISPE VARGAS RENATO \nTITO CHURA RENZO ROBIÑO\nNSECA LIZÁRRAGA CINTHIA YANETH\n\n', '2026-08-04 16:42:28.118000', '2026-08-07 13:20:13.074000', '2026-08-07 13:20:13.090000', 7, 1, NULL, 'Objetivo General:\nDesarrollar y validar un sistema de inteligencia artificial espacio-temporal y explicable para la predicción probabilística de heladas en la región Puno, capaz de identificar patrones climáticos complejos y generar alertas\n\nObjetivos Específicos:\nOE1. Integrar y preprocesar datos meteorológicos, geográficos y climáticos provenientes de fuentes abiertas para la construcción de una base de datos espaciotemporal orientada a la predicción de heladas en la región Puno.\nOE2. Diseñar e implementar modelos de inteligencia artificial espaciotemporal para identificar patrones climáticos asociados a la ocurrencia de heladas y estimar probabilísticamente su riesgo de ocurrencia.\nOE3. Incorporar técnicas de Inteligencia Artificial Explicable (XAI) para identificar e interpretar la influencia de las variables meteorológicas y geográficas en las predicciones generadas por el sistema.\nOE4. Desarrollar y validar un sistema de alerta temprana que permita visualizar, comunicar y monitorear', 'SISTEMA FROST-PREDICT AI PARA LA ALERTA TEMPRANA DE HELADAS MEDIANTE MODELOS ESPACIO-TEMPORALES EXPLICABLES EN LA REGIÓN PUNO, PERÚ', 'LEONID ALEMAN GONZALES', 93.83),
	(404, 'ugqqno2o5chbyx4z655b2nyl', 'CLIMATECH UNA PUNO', '2026', 'INGENIERÍA  MECÁNICA  ELÉCTRICA, ELECTRÓNICA Y SISTEMAS', 'INGENIERÍA DE SISTEMAS', 10000.00, 'INTELIGENCIA ARTIFICIAL, SISTEMAS COMPUTACIONALES Y SISTEMAS BIOINSPIRADOS', 'Chura Yupa Franklin Alfred\nMayta Guzman Fabricio \nTipo Catunta Roy Jesus Aldair', '2026-08-04 17:28:00.811000', '2026-08-07 13:20:44.702000', '2026-08-07 13:20:44.727000', 7, 1, NULL, 'Objetivo General:\nDesarrollar y validar una arquitectura híbrida de IA generativa con Transformers fundacionales e indexación multidimensional para el pronóstico en tiempo real de fenómenos meteorológicos extremos en el Altiplano peruano.\n\nObjetivos Específicos:\nOE1. Construir un dataset multimodal para Puno cruzando SENAMHI, Open-Meteo, GOES-R y ERA5 (2015-2025).\nOE2. Implementar la capa de persistencia con R*-Tree sobre MongoDB frente a B-Tree de control, con Octree 3D como prueba de concepto.\nOE3. Ejecutar fine-tuning de Chronos-2 sobre telemetría andina y evaluar Pangu-Weather como baseline neuronal vía ECMWF ai-models.\nOE4. Comparar la arquitectura propuesta contra el WRF 25 km del SENAMHI mediante MAE, RMSE, CRPS y skill score, con ANOVA de medidas repetidas.', 'INTELIGENCIA ARTIFICIAL GENERATIVA Y TRANSFORMERS PARA EL PRONÓSTICO EN TIEMPO REAL DE FENÓMENOS METEOROLÓGICOS EXTREMOS EN EL ALTIPLANO PERUANO', 'HUGO YOSEF GOMEZ QUISPE', 86.83),
	(405, 'wytsfji4j2j3fmpy9b53r2s8', 'SEMILLERO DE INVESTIGACIÓN EN EDUCACIÓN FÍSICA Y LIDERAZGO FEMENINO” (SIEFLF)', '2026', 'CIENCIAS DE LA EDUCACIÓN', 'EDUCACION FISICA', 10000.00, 'PSICOMOTRICIDAD', 'MAYTA DE LA RIV ZENAYDA LUCERO \nMAMANI ALMONTE YOMARA NOELIA\nCOLQUE SALAS YASMY YAMILE ', '2026-08-04 17:38:22.712000', '2026-08-07 13:21:09.839000', '2026-08-07 13:21:09.865000', 7, 1, NULL, 'Objetivo General:\nDeterminar el efecto del programa de educación psicomotriz en el neurodesarrollo infantil de los niños de educación inicial de las Islas Flotantes de los Uros expuestos a condiciones de altitud\n\nObjetivos Espécificos;\n- Evaluar el nivel del neurodesarrollo infantil en los niños de educación inicial antes de la aplicación del programa.\n- Aplicar el programa de educación psicomotriz dirigido a niños de educación inicial en condiciones de altitud extrema.\n- Comparar los resultados del neurodesarrollo infantil antes y después de la aplicación del programa', 'NEURODESARROLLO INFANTIL EN CONDICIONES EXTREMAS DE ALTITUD: IMPACTO DEL PROGRAMA DE EDUCACIÓN PSICOMOTRIZ EN NIÑOS DE EDUCACIÓN INICIAL DE LAS ISLAS FLOTANTES DE LOS UROS', 'DOMETILA MAMANI JILAJA', 84.00),
	(406, 'ptwvfgjrp6okx17mfvnqv3l8', 'GRUPO DE INVESTIGACIONES ANTROPOLÓGICAS - GIA', '2026', 'CIENCIAS  SOCIALES', 'ANTROPOLOGÍA', 10000.00, 'ANÁLISIS DE PROCESOS SOCIALES, FAMILIAS: REALIDADES, CAMBIO Y DINÁMICAS DE INTERVENCIÓN', 'Quispe Condori Tamara Akemi\nPanca Quispe Sarely Betsi\nTarqui Tique Lizet Lucero\nCcama Llatasi Jherson Jhoseph\nMaquera Apaza Ruth Mayely\n', '2026-08-04 17:37:08.237000', '2026-08-07 13:21:36.063000', '2026-08-07 13:21:36.078000', 7, 1, NULL, 'Objetivo General:\nAnalizar las trayectorias de estudiantes peruanos que se movilizan por estudios superiores en universidades en el país de Bolivia\n\nObjetivos Específicos:\n1. Identificar las características socioeconómicas de los estudiantes peruanos que realizan estudios de educación superior en Bolivia.\n2. Analizar los factores sociales, económicos y educativos que influyen en la decisión de los estudiantes peruanos de realizar estudios superiores en Bolivia\n3. Describir las dificultades, problemáticas y oportunidades de los estudiantes universitarios peruanos en Bolivia durante y después de los estudios superiores', 'TRAYECTORIAS FORMATIVAS DE ESTUDIANTES PERUANOS EN BOLIVIA: DESAFÍOS, OPORTUNIDADES Y EXPECTATIVAS DE FUTURO', 'DUVERLY JOAO INCACUTIPA LIMACHI', 84.42),
	(407, 'tunglajczpt3gj9fhjakfsyk', 'ODONTOCIENCIA Y SALUD', '2026', 'CIENCIAS DE LA SALUD', 'ODONTOLOGÍA', 10000.00, 'DIAGNÓSTICO, TRATAMIENTO Y REHABILITACIÓN DEL SISTEMA ESTOMATOGNÁTICO', 'ACERO JIMENEZ LEYDI GIOVANNA\nESCOBAR MAMANI YADHIRA LIZBETH\nMAYTA FLORES LIZBETH NAYELI\nMAMANI RIOS HOLINDA\nCOPACONDORI RAMOS GLISETH GLIS\n\n\n', '2026-08-04 17:35:52.979000', '2026-08-07 13:22:02.924000', '2026-08-07 13:22:02.939000', 7, 1, NULL, 'Objetivo General:\nEvaluar el efecto de las infusiones tradicionales altoandinas (muña, coca y eucalipto) sobre la estabilidad cromática de resinas compuestas mediante un estudio experimental in vitro.\n\nObjetivos Específicos:\n- Determinar la estabilidad cromática de las resinas compuestas expuestas a infusión de muña (Minthostachys mollis) durante 1 día, 3 días, 5 y 7 días.\n- Determinar la estabilidad cromática de las resinas compuestas expuestas a infusión de coca (Erythroxylum coca) durante 1 día, 3 días, 5 y 7 días.\n- Determinar la estabilidad cromática de las resinas compuestas expuestas a infusión de eucalipto (Eucalyptus globulus) durante 1 día, 3 días, 5 y 7 días.\n- Comparar la estabilidad cromática de las resinas compuestas expuestas a las diferentes infusiones tradicionales altoandinas y al grupo control según el tiempo de exposición.', 'EFECTO DE INFUSIONES TRADICIONALES ALTOANDINAS SOBRE LA ESTABILIDAD CROMÁTICA DE RESINAS COMPUESTAS, PUNO PERÚ', 'NELLY BEATRIZ QUISPE MAQUERA', 84.58),
	(408, 's1ujhwujmght3jjndrqu6l3g', 'SEMILLEROS DE SERENDIPIA EN TRABAJO SOCIAL', '2026', 'TRABAJO SOCIAL', 'TRABAJO SOCIAL', 10000.00, 'INSTITUCIONALIDAD, CONFLICTOS Y GESTIÓN AMBIENTAL', 'Mamani Rayme Jane Javelin \nQuispe Huahuacondori Edward Jhon\nTotora Gutierrez Griselda \nBenavente Ticona Yoselim Adai \nFlores Ordoño Daysi Maribel \nQuispe Itusaca Katy Carolina', '2026-08-04 17:30:59.695000', '2026-08-07 13:22:32.728000', '2026-08-07 13:22:32.745000', 7, 1, NULL, 'Objetivo General:\nComprender las representaciones institucionales y los discursos de la sociedad civil sobre la gestión ambiental del Lago Titicaca, identificando las brechas entre la normativa y la práctica, así como las\n\nObjetivos Específicos:\na. Interpretar los discursos y narrativas construidas por los representantes del Estado (municipalidades, Gobierno Regional, Ministerio del Ambiente) sobre la contaminación y la gestión de\náreas degradadas del Lago Titicaca.\nb. Explorar las percepciones de las organizaciones de la sociedad civil (ONGs, asociaciones ambientales) respecto a la pertinencia y eficacia de las políticas públicas ambientales.\nc. Develar las brechas y contradicciones existentes entre la normativa ambiental y las prácticas reales de gestión en el territorio.\nd. Analizar las percepciones de los actores institucionales y sociales sobre la participación comunitaria en la gestión ambiental del Lago Titicaca.\ne. Contrastar los puntos', 'REPRESENTACIONES INSTITUCIONALES Y POLÍTICAS PÚBLICAS SOBRE LA GESTIÓN AMBIENTAL DEL LAGO TITICACA', 'MARIA EMMA ZUÑIGA VASQUEZ', 86.17),
	(409, 'e57yqe4savtlveavquvzmkzg', 'IMPACTO DE LA EDUCACIÓN AMBIENTAL EN EL CONSUMO DE AGUA EN INSTITUCIONES EDUCATIVAS EN LA CIUDAD DE PUNO – “EDUAGUA PUNO”', '2026', 'INGENIERÍA AGRÍCOLA', 'INGENIERÍA AGRÍCOLA', 10000.00, 'CONSERVACIÓN Y APROVECHAMIENTO DE RECURSOS NATURALES, RESPONSABILIDAD SOCIAL DE LA EDUCACIÓN, RECURSOS HÍDRICOS', 'Zurita Zurita Brayan Dante\nHuanca Tito Wilber Jesús\nChipana Choque Ana Luz\nTurpo Almanza Jherson Denis Abel\nVilca Tapia Alex Franklin\n\n', '2026-08-04 17:26:27.302000', '2026-08-07 13:22:55.071000', '2026-08-07 13:22:55.085000', 7, 1, NULL, 'Objetivo General:\nEvaluar el impacto de la educación ambiental en el consumo de agua en instituciones educativas de la ciudad de Puno.\n\nObjetivos Específicos:\nAnalizar los hábitos de consumo de agua en instituciones educativas seleccionadas.\nEvaluar el nivel de conocimiento ambiental de estudiantes.\nDeterminar los cambios en el consumo de agua tras la implementación de acciones educativas.\nProponer estrategias educativas para el uso responsable del agua.', 'EVALUACIÓN DEL IMPACTO DE LA EDUCACIÓN AMBIENTAL EN EL CONSUMO HÍDRICO ESCOLAR: UN ANÁLISIS COMPARATIVO EN LA CIUDAD DE PUNO', 'JOSE ANTONIO MAMANI GOMEZ', 86.83),
	(410, 'jn4l97rwq72wmt1fz3t1xxx2', 'YUYAY, CULTURA Y COGNICIÓN', '2026', 'CIENCIAS  SOCIALES', 'DEPARTAMENTO DE HUMANIDADES', 10000.00, 'SOCIOLINGÜÍSTICA E INTERCULTURALIDAD', 'Yto Goyzueta Andy Veicker\nCanaza Huacasi Cesar Augusto\nCajia Mamani Jerry Wuelfredo\nMamani Castrillo Noe Lizardo\nMamani Ariaca Milagros Juana\nCastillo Apaza Fanny Esther', '2026-08-04 17:22:43.161000', '2026-08-10 03:42:18.677000', '2026-08-10 03:42:18.701000', 7, 1, NULL, 'Objetrvo General:\nComprender las narrativas de sufrimiento psíquico y las experiencias de transición sociocultural en estudiantes universitarios de origen rural en la Universidad Nacional del Altiplano\n\nObjetivos Específicos:\nDescribir las experiencias de transición sociocultural y los significados atribuidos al sufrimiento psíquico durante la incorporación a la vida universitaria.\nIdentificar en las narrativas estudiantiles los factores socioculturales de vulnerabilidad asociados al riesgo suicida, tales como el desarraigo, discriminación, aislamiento y tensiones identitarias.\nReconocer los recursos de resistencia cultural, saberes ancestrales y estrategias de afrontamiento colectivo desplegados por los estudiantes para sostener su bienestar.\nProponer lineamientos institucionales para el diseño de estrategias de prevención del riesgo suicida con pertinencia cultural en la Universidad Nacional del Altiplano.', '"ENTRE DOS MUNDOS: NARRATIVAS DE SUFRIMIENTO PSÍQUICO Y TRANSICIÓN SOCIOCULTURAL EN ESTUDIANTES DE ORIGEN   RIURAL DE LA UNA PUNO. APORTES PARA PREVENIR LA CONDUCTA SUICIDA"  ', 'MARIBEL CEFERINA PUMACAHUA YUCRA', 87.92),
	(411, 'h4roou7g2kfh8a0edtq9fmm9', 'ENERGIAS RENOVABLES', '2026', 'INGENIERÍA QUÍMICA', 'INGENIERÍA QUÍMICA', 10000.00, 'TECNOLOGÍAS AMBIENTALES Y ENERGÍAS RENOVABLES, RECUPERACIÓN, CONSERVACIÓN Y TRANSFORMACIÓN DE RECURSOS NATURALES, ENERGÍAS RENOVABLES', 'CHURAYRA MAMANI, ROSSMERY ANGELA\nACRA ATAMASI, ROSS MERY\nHUAMAN MENDOZA, VANE SHEIRLY\nCONDORI MAMANI, RUTH ALEXANDRA\nIRURI LEON, NATALI LECINCA', '2026-08-04 17:08:58.550000', '2026-08-10 03:44:48.004000', '2026-08-10 03:44:48.033000', 7, 1, NULL, 'Objetivo General:\nOptimizar y modelar un sistema híbrido foto-electro-Fenton de flujo continuo para la remoción de Cr(VI) en aguas residuales de curtiembre, evaluando el efecto de los parámetros operativos clave sobre la \n\nObjetivos Específicos:\n•	Caracterizar fisicoquímicamente las aguas residuales de curtiembre mediante la determinación de Cr(VI), cromo total, DQO, pH, conductividad, turbidez, ORP y sólidos suspendidos, a fin de establecer las condiciones iniciales del efluente a tratar.\n•	Evaluar el efecto de la densidad de corriente, la concentración de H₂O₂ y el caudal sobre la remoción de Cr(VI), la reducción de DQO, la turbidez y el consumo energético específico en el sistema híbrido foto-electro-Fenton de flujo continuo.\n•	Optimizar las condiciones operativas del sistema mediante la metodología de superficie de respuesta, estableciendo los valores óptimos de densidad de corriente, concentración de H₂O₂ ', 'OPTIMIZACIÓN Y MODELAMIENTO DE UN SISTEMA HÍBRIDO FOTO-ELECTRO-FENTON EN FLUJO CONTINUO PARA LA REMOCIÓN DE CR(VI) EN AGUAS RESIDUALES DE CURTIEMBRE', 'JOSE NESTOR MAMANI QUISPE', 93.17),
	(412, 'exugui5j6l6fid5k5e1hw2ve', 'DATANOVA LAB', '2026', 'INGENIERÍA ESTADÍSTICA E INFORMÁTICA', 'INGENIERÍA ESTADÍSTICA E INFORMÁTICA', 10000.00, 'ANÁLISIS MULTIVARIADO, BIG DATA, MINERÍA DE DATOS E INVESTIGACIÓN DE MERCADOS', 'YANARICO HUANCA, FLOR MELANY\nLAURA LIVISE, YEFERSON DARIUN\nBUSTINCIO SUAÑA, ANGIE NAHOMI\nGONZÁLES QUISPE, WILFREDO\nPAMPA HUAMAN, WILSON HUGO', '2026-08-04 17:46:37.819000', '2026-08-10 03:46:15.504000', '2026-08-10 03:46:15.526000', 7, 1, NULL, 'Objetivo General:\nDesarrollar un modelo predictivo de la producción de quinua en la región de Puno (Perú) basado en la transformada wavelet deformada para la selección óptima de variables agroclimáticas y la \n\nObjetivos Específicos:\n1. Recopilar y sistematizar datos históricos de producción de quinua y variables agroclimáticas (temperatura, precipitación, humedad, radiación solar) en la región de Puno para el período de análisis definido.\n\n2. Aplicar el método de selección de características mediante wavelets deformadas para identificar las variables agroclimáticas más influyentes en la producción de quinua con alta probabilidad.\n\n3. Ajustar modelos de regresión no paramétrica (regresión kernel local y B-splines) con las variables seleccionadas para estimar la producción de quinua.\n\n4. Evaluar y comparar el desempeño predictivo del modelo propuesto frente a métodos de regresión clásica mediante métricas estadísticas apropiadas.\n', 'PREVISIÓN DE LA PRODUCCIÓN DE QUINUA EN PUNO (PERÚ), BASADA EN LA TRANSFORMADA WAVELET, CONSIDERANDO VARIABLES AGROCLIMÁTICAS', 'GODOFREDO QUISPE MAMANI', 78.00),
	(413, 'n3krh1cxv60uoibegicif0h3', 'COMPOST  TRANSFORMANDO NUESTROS RESIDUOS EN VIDA', '2026', 'CIENCIAS AGRARIAS', 'INGENIERÍA AGRONÓMICA', 10000.00, 'DESARROLLO DE SISTEMAS AGROPECUARIOS', 'MAMANI ARCE, REYNALDO\nMAMANI ITO, KRICELLY JAZMIN\nHUANCA GALLEGOS, YHOMARA YOSELIN PILAR\nTOMA AQUINO, RUIZ VIDAL\nPOMARI HUAYHUA, MIDIAN\nQUISPE CHAMBI, BLANCA NIEVES\n', '2026-08-04 17:45:38.277000', '2026-08-10 03:47:37.370000', '2026-08-10 03:47:37.395000', 7, 1, NULL, 'Objetivo General:\nSe evaluará el compostaje aeróbico de residuos universitarios con estiércoles (ovino, vacuno, cuy) enriquecido con Azospirillum brasilense, midiendo su efecto en el proceso, propiedades fisicoquímicas y calidad biofertilizante.\n\nObjetivos Específicos:\nCaracterizar los residuos del comedor y estiércoles (ovino, vacuno, cuy) para formular mezclas estables con humedad del 50% -60% y relación C:N inicial de 25:1 a 30:1.\n\nMonitorear la temperatura y oxigenación en las fases mesófila y termófila ( 55°C) para definir el momento óptimo de inoculación de Azospirillum brasilense en el enfriamiento.\n\nEvaluar las propiedades fisicoquímicas, en concentración de NPK y madurez y viabilidad bacteriana (UFC/g) del compost final, determinando el tratamiento con mejor calidad biofertilizante.', '"OPTIMIZACIÓN DEL PROCESO DE COMPOSTAJE DE RESIDUOS ORGÁNICOS UNIVERSITARIOS MEDIANTE LA INOCULACIÓN DE BACTERIAS PROMOTORAS DEL CRECIMIENTO VEGETAL (BPCP) EN PUNO"', 'RONY ABEL CIPRIAN CARREON', 79.08),
	(414, 'y6f6hba8yi07vtt9ms5w3erg', 'CALIBRATECH PRECISION GROUP', '2026', 'INGENIERÍA  MECÁNICA  ELÉCTRICA, ELECTRÓNICA Y SISTEMAS', 'INGENIERÍA MECÁNICA ELÉCTRICA', 10000.00, 'CONTROL DE PROCESOS', 'HUAHUALA MORA , YAMPIER JOSE\nCUTIPA RAFAEL, CHRISTIAN\nCHURA LLANOS, MARCO ANTONIO\nCUTIPA CHOQUEHUANCA , EDSON', '2026-08-04 17:44:31.747000', '2026-08-10 03:48:53.014000', '2026-08-10 03:48:53.041000', 7, 1, NULL, 'Objetivo General:\nDiseñar e implementar un prototipo automatizado para la calibración de detectores de metales en fajas transportadoras, evaluando su desempeño mediante pruebas experimentales\n\nObjetivos Específicos:\nAnalizar el funcionamiento de detectores de metales utilizados en fajas transportadoras mineras.\nDiseñar un sistema electromecánico automatizado para el desplazamiento controlado de patrones metálicos.\nImplementar un sistema de control basado en microcontrolador o PLC para ejecutar rutinas automáticas de calibración.\nEvaluar la precisión y repetibilidad del prototipo mediante pruebas experimentales.', 'DISEÑO E IMPLEMENTACIÓN DE UN PROTOTIPO AUTOMATIZADO PARA LA CALIBRACIÓN DE DETECTORES DE METALES EN FAJAS TRANSPORTADORAS PARA LA INDUSTRIA MINERA.', 'JULIO FREDY CHURA ACERO', 79.75),
	(415, 'bx0qhsx060ildpw0f9j4ec3t', 'SEMILLERO DE INVESTIGACIÓN PEDAGÓGICA, EDUCATIVA Y SOCIAL WIÑAY (SIPES)', '2026', 'CIENCIAS DE LA EDUCACIÓN', 'EDUCACIÓN PRIMARIA', 10000.00, 'PERSPECTIVAS TEÓRICAS DE LA EDUCACIÓN', 'Pacco Mamani, Flor Gianella\nGonzales Quispe, Maryori Luisa\nCCORI HUANCA, JORGE LUIS\nMamani Salinas , Maria Asunta\nJilaja Salluca , Yunsu Alison\nCHAMBI CALLOHUANCA, Aymee Elida', '2026-08-04 17:43:30.828000', '2026-08-10 03:50:39.929000', '2026-08-10 03:50:39.958000', 7, 1, NULL, 'Objetivo General:\nAnalizar la influencia de la ciudadanía digital sobre el uso responsable de la inteligencia artificial a través del pensamiento crítico frente a la IA en estudiantes universitarios.\n\nObjetivos Específicos;\nDeterminar el nivel de ciudadanía digital de los estudiantes universitarios.\nAnalizar la relación entre ciudadanía digital y pensamiento crítico frente a la IA.\nAnalizar la relación entre pensamiento crítico frente a la IA y uso responsable de la IA.\nEvaluar el efecto directo de la ciudadanía digital sobre el uso responsable de la IA.\nEvaluar el efecto mediador del pensamiento crítico frente a la IA.', 'CIUDADANÍA DIGITAL, PENSAMIENTO CRÍTICO Y USO RESPONSABLE DE LA INTELIGENCIA ARTIFICIAL EN ESTUDIANTES UNIVERSITARIOS', 'VIDNAY NOEL VALERO ANCCO', 79.92),
	(417, 'fwdjz1lh0by9shc2k80fale4', 'ALIMENTOS FUNCIONALES Y NUTRACEÚTICOS EN INVESTIGACIÓN (NUTRIALFA)', '2026', 'INGENIERÍA QUÍMICA', 'INGENIERÍA QUÍMICA', 10000.00, 'PROCESAMIENTO DE ALIMENTOS, FORMULACIÓN, EVALUACIÓN Y GESTIÓN DE PROYECTOS Y EMPRESAS CON ALIMENTOS, NUTRICIÓN Y SALUD, INNOVACIÓN, ANÁLISIS Y CONTROL DE LOS ALIMENTOS EN EL SISTEMA ALIMENTARIO', 'Romero Tisnado, Marcelo Denis\nParhuayo Cornejo , Diego Andre\nQuispe Vidal , Yordan Ronaldho\nCondori Mendoza , Jesús Ronaldo\nJihuallanca Ticona , Lesly Yamileth\nMamani García , María\n', '2026-08-04 17:42:22.496000', '2026-08-10 03:52:23.912000', '2026-08-10 03:52:23.930000', 7, 1, NULL, 'Objetivo General:\nElaborar y evaluar nuggets a base de trucha arcoíris (Oncorhynchus mykiss) enriquecidos con harinas de tarwi y quinua como alternativa alimentaria funcional rica en proteínas.\n\nObjetivos Específicos:\n- Formular nuggets de trucha arcoíris con diferentes proporciones de harina de tarwi y harina de quinua.\n- Determinar la composición nutricional de los nuggets elaborados, considerando humedad, proteína, grasa, cenizas, carbohidratos y valor energético.\n- Determinar la calidad microbiológica de los nuggets elaborados para verificar condiciones básicas de inocuidad alimentaria.\n- Evaluar la aceptabilidad sensorial de los nuggets mediante atributos como color, olor, sabor, textura y aceptación general.', 'ELABORACIÓN DE NUGETS A BASE DE TRUCHA ARCOIRIS (ONCORHYCHUS MYKISS) ENRIQUESIDOS CON HARINAS DE TARWI Y QUINUA COMO ALTERNATIVA ALIMENTARIA FUNCIONAL RICA EN PROTEINA', 'EDITH TELLO PALMA', 82.00),
	(418, 'jgpxq8muu4b0v5p6dapp4sdg', 'ADSOBENTES 3D - IQ', '2026', 'INGENIERÍA QUÍMICA', 'INGENIERÍA QUÍMICA', 10000.00, 'CALIDAD AMBIENTAL', 'GARCIA VILCA, FRANCHESKA NAHOMI\nMAMANI CUNO , GABY JIMENA\nHUANCOLLO CHAMBI , YENI ROSMEDY\nCHURATA MULLISACA , HELEN VANESA\nRAMOS VELÁSQUEZ , ANDRÉ\nVILCA SÁNCHEZ , HELEN GRISEL', '2026-08-04 17:41:27.734000', '2026-08-10 03:53:34.734000', '2026-08-10 03:53:34.754000', 7, 1, NULL, 'Objetivo General:\nDesarrollar adsorbentes impresos en 3D modificados con materiales naturales para la remoción de arsénico y plomo en aguas contaminadas del Altiplano peruano.\n\nObjetivos Específicos:\n•	Diseñar estructuras adsorbentes impresas en 3D con diferentes geometrías porosas. \n•	Modificar superficialmente las estructuras utilizando zeolita, biochar, bentonita y óxidos de hierro. \n•	Evaluar la capacidad de adsorción de arsénico y plomo. \n•	Determinar la cinética e isotermas de adsorción. ', 'DESARROLLO DE ADSORBENTES IMPRESOS EN 3D MODIFICADOS CON MATERIALES NATURALES PARA LA REMOCIÓN DE ARSÉNICO Y PLOMO EN AGUAS CONTAMINADAS DEL ALTIPLANO PERUANO', 'TEOFILO DONAIRES FLORES', 82.67),
	(419, 'bf8mdpzz381b7ethrllrjlr5', 'SENSORES 3D - IQ', '2026', 'INGENIERÍA QUÍMICA', 'INGENIERÍA QUÍMICA', 10000.00, NULL, 'CONDORI ARAPA, HAIDER JHAK\nCHAIÑA YANA, LEYDI YUDITH\nRAMOS APAZA, ROSMERY STEFANY\nCHAVEZ MAMANI, CRISTOFHER\nCONDORI MENDOZA, JESÚS RONALDO\nMAMANI GARCÍA, MARÍA', '2026-08-04 17:40:48.202000', '2026-08-10 03:54:36.262000', '2026-08-10 03:54:36.283000', 7, 1, NULL, 'Objetivo General:\nDesarrollar y validar sensores electroquímicos impresos en 3D para la determinación de contaminantes emergentes en aguas superficiales de la Bahía Interior del Lago Titicaca.\n\nObejtivos Específicos:\n●	Diseñar y fabricar electrodos conductores mediante impresión 3D FDM. \n●	Activar y caracterizar electroquímicamente los sensores desarrollados. \n●	Optimizar las condiciones analíticas para la detección de contaminantes emergentes. \n●	Evaluar la sensibilidad, precisión y reproducibilidad del sensor. ', 'DESARROLLO DE SENSORES ELECTROQUÍMICOS IMPRESOS EN 3D PARA LA DETERMINACIÓN DE FÁRMACOS Y CONTAMINANTES EMERGENTES DE LA BAHÍA INTERIOR DEL LAGO TITICACA, PUNO', 'TEOFILO DONAIRES FLORES', 82.75),
	(420, 'jmqr6p1m8j6qv5djpb7dcwo6', 'REDES QUE INSPIRAN EL TURISMO MODERNO', '2026', 'CIENCIAS  SOCIALES', 'TURISMO', 10000.00, 'GESTIÓN DE DESTINOS TURÍSTICOS', 'PAREDES MAMANI, LIZ YOSELYN\nESTEBAN MARCANI, MARGOT YESENIA\nSOTO SANTANA, ERICK MANUEL\nTTITO COAQUIRA, VIVIANA YOLY', '2026-08-04 17:40:02.300000', '2026-08-10 03:55:47.784000', '2026-08-10 03:55:47.801000', 7, 1, NULL, 'Obejtivo General:\nEvaluar el efecto de la implementación de WhatsApp Business, como proceso de transferencia de tecnología, en la comercialización del turismo comunitario en comunidades del entorno del Lago Titicaca, región Puno, \n\nObjetivos Específicos:\n1.	Evaluar el efecto de la implementación de WhatsApp Business en el número de consultas turísticas de los emprendimientos de turismo comunitario del entorno del Lago Titicaca.\n2.	Evaluar el efecto de la implementación de WhatsApp Business en el tiempo de respuesta en la atención a los turistas de los emprendimientos de turismo comunitario.\n3.	Evaluar el efecto de la implementación de WhatsApp Business en la captación de clientes de los emprendimientos de turismo comunitario del entorno del Lago Titicaca.\n4.	Evaluar los cambios producidos en los indicadores de comercialización turística después de la implementación de WhatsApp Business como herramienta ', 'TRANSFERENCIA TECNOLÓGICA MEDIANTE EL USO DE WHATSAPP BUSINESS PARA FORTALECER LA COMERCIALIZACIÓN DEL TURISMO COMUNITARIO EN PUNO', 'NOEMI EMPERATRIZ CAYO VELASQUEZ', 83.67),
	(421, 'nl8441sxzd6pqeusa5pz2xj4', 'VOCES EN MOVIMIENTO DE TRABAJO SOCIAL', '2026', 'TRABAJO SOCIAL', 'TRABAJO SOCIAL', 10000.00, 'FAMILIAS: REALIDADES, CAMBIO Y DINÁMICAS DE INTERVENCIÓN', 'BUSTINZA VARGAS, JUANA VICTORIA', '2026-08-04 17:39:34.156000', '2026-08-10 03:57:05.703000', '2026-08-10 03:57:05.722000', 7, 1, NULL, 'Objetivo General: \nComprender las experiencias comunitarias del desarrollo de bienestar integral construidas por la población del distrito de Cojata frente a la contaminación del río Suches durante el año 2026.\n\nObjetivos Específicos:\nOE1: Comprender las experiencias de vulnerabilidad vividas por la población del distrito de Cojata frente a la contaminación del río Suches.\nOE2: Analizar los procesos de construcción del bienestar integral desarrollados por la población frente a la contaminación del río Suches.', '"EXPERIENCIAS COMUNITARIAS DEL DESARROLLO DE BIENESTAR INTEGRAL ANTE LA CONTAMINACIÓN DEL RÍO SUCHES EN COJATA - 2026"', 'JUANA VICTORIA BUSTINZA VARGAS', 83.83),
	(422, 'bgw8wb0xu7snetamf28yjwtw', 'AYLLU DEL SABER: UNIDOS POR LA INVESTIGACIÓN EDUCATIVA', '2026', 'CIENCIAS DE LA EDUCACIÓN', 'EDUCACIÓN SECUNDARIA', 10000.00, NULL, 'Parillo Pineda, Fiorela Felicitas\nIlaquita Mamani , Jacobo Orestes\nLaura Apaza, Erika Yuly\nApaza Cabrera , Yeraldine Marina', '2026-08-04 17:33:32.481000', '2026-08-10 03:58:05.097000', '2026-08-10 03:58:05.123000', 7, 1, NULL, 'Objetivo General:\nDescribir los sesgos de género en la elección de carreras STEM en estudiantes de educación secundaria de la ciudad de Puno en el año 2026.\n\nObjetivos Específicos:\n•	Identificar las creencias estereotipadas de género asociadas a las carreras STEM. \n•	Describir el nivel de autoeficacia percibida en áreas STEM. \n•	Caracterizar las percepciones sobre roles de género en la elección de carrera profesional. \n•	Describir las expectativas familiares y sociales vinculadas a la elección de carreras STEM. ', '“SESGOS DE GÉNERO EN LA ELECCIÓN DE CARRERAS STEM EN ESTUDIANTES DE EDUCACIÓN SECUNDARIA DE LA CIUDAD DE PUNO, 2026”', 'INDIRA IRACEMA GOMEZ ARTETA', 84.58),
	(423, 'erj30udo43dpzbcv4prsav8m', '“SEMILLERO DE INVESTIGACIÓN MONTESSORI” (SIM)', '2026', 'CIENCIAS DE LA EDUCACIÓN', 'EDUCACIÓN PRIMARIA', 10000.00, 'PERSPECTIVAS TEÓRICAS DE LA EDUCACIÓN, RESPONSABILIDAD SOCIAL DE LA EDUCACIÓN', 'HUMPIRI PACOMPIA , EDWIN\nAGUILAR CHOQUEHUANCA , SHAYLA YESSICA\nAYNA CONDORI , DANITZA\nCOTRADO CONDORI , YESSICA DEYSI', '2026-08-04 17:33:03.304000', '2026-08-10 03:59:20.885000', '2026-08-10 03:59:20.901000', 7, 1, NULL, 'Objetivo General:\nDeterminar el efecto que tiene la implementación de entornos lúdicos en el fortalecimiento de las competencias socioemocionales y en el desarrollo del pensamiento crítico matemático en los estudiantes \n\nObjetivos Específicos:\n-Analizar la influencia que ejerce la aplicación de espacios lúdicos en el fortalecimiento de las competencias socioemocionales.\n-Identificar el impacto de la incorporación de entornos lúdicos en el desarrollo del pensamiento crítico matemático en los estudiantes.\n-Contrastar los resultados obtenidos en el pretest y el postest con el fin de evidenciar variaciones en el nivel de desarrollo de las habilidades socioemocionales en los estudiantes.\n-Comparar diferencias entre los resultados del pretest y el postest para determinar cambios en el desarrollo del pensamiento matemático en los estudiantes.', 'LOS ESPACIOS LÚDICOS EN EL DESARROLLO DE HABILIDADES SOCIALES Y EL PENSAMIENTO MATEMÁTICO EN LOS NIÑOS DE EDUCACIÓN PRIMARIA', 'DANITZA LUISA SARDON ARI', 84.83),
	(424, 'sikow02ofprpcbwpk2in7ez8', 'EXDUCERE', '2026', 'CIENCIAS DE LA EDUCACIÓN', 'EDUCACIÓN SECUNDARIA', 10000.00, 'GESTIÓN EDUCATIVA Y DESARROLLO INSTITUCIONAL', 'ARIAS LIZARES, ANDRES', '2026-08-04 17:32:38.614000', '2026-08-10 04:00:25.094000', '2026-08-10 04:00:25.113000', 7, 1, NULL, 'Objetivo General:\nAnalizar las diferencias en el nivel de comprensión del desarrollo de competencias entre los estudiantes de las áreas biomédicas, sociales e ingenierías de la Universidad Nacional del Altiplano de Puno.\n\nObjetivos Específicos:\nPrecisar las diferencias existentes en la comprensión conceptual sobre las competencias entre los estudiantes de las áreas biomédicas, sociales e ingenierías de la Universidad Nacional del Altiplano de Puno.\nEstablecer las diferencias existentes en la comprensión del proceso de desarrollo de competencias entre los estudiantes de las áreas biomédicas, sociales e ingenierías de la Universidad Nacional del Altiplano de Puno.\nExaminar las diferencias en la comprensión de la evaluación por competencias entre los estudiantes de las áreas biomédicas, sociales e ingenierías de la Universidad Nacional del Altiplano de Puno.\nIdentificar las diferencias en la comprensión de la aplicabilidad de las ', 'DIFERENCIAS EN LA COMPRENSIÓN DEL DESARROLLO DE COMPETENCIAS ENTRE ESTUDIANTES DE LAS ÁREAS BIOMÉDICAS, SOCIALES E INGENIERÍAS DE LA UNIVERSIDAD NACIONAL DEL ALTIPLANO', 'ANDRES ARIAS LIZARES', 85.00),
	(425, 'ds0msvlqjrylgx1pfzcos4mj', 'RESILIENCIA COMUNITARIA Y CULTURA DE PREVENCIÓN EN EL CERRO AZOGUINE – “PREVENCIÓNAZOGUINE”', '2026', 'INGENIERÍA AGRÍCOLA', 'INGENIERÍA AGRÍCOLA', 10000.00, 'GESTIÓN DE RIESGOS Y CAMBIO CLIMÁTICO, ORDENAMIENTO TERRITORIAL Y MEDIO AMBIENTE', 'Quispe Vilcanqui , Juan Carlos\nLope Lope, Freddy Clinton\nAcero Ramos, Viviana Balbina\nHuillca Pari , Daniel Mathias\nContreras Atencio, Eva Yonmy', '2026-08-04 17:31:39.675000', '2026-08-10 04:01:59.653000', '2026-08-10 04:01:59.678000', 7, 1, NULL, 'Objetivo General:\nAnalizar la resiliencia comunitaria y la cultura de prevención frente a riesgos socioambientales en la población del cerro Azoguine.\n\nObejtivos Específicos:\nIdentificar los principales riesgos y amenazas presentes en el cerro Azoguine.\nEvaluar el nivel de resiliencia comunitaria ante situaciones de emergencia.\nAnalizar la percepción del riesgo y las prácticas de prevención de la población.\nProponer estrategias para el fortalecimiento de la cultura de prevención comunitaria.', 'ESTRATEGIAS DE FORTALECIMIENTO DE LA CULTURA DE PREVENCIÓN COMUNITARIA ANTE DESASTRES NATURALES EN EL SECTOR AZOGUINE', 'JOSE ANTONIO MAMANI GOMEZ', 85.92),
	(427, 'c480r0vmwignc1c5w2fkm0hv', 'SEMILLERO DE INVESTIGACION EN SEGURIDAD DE INFORMACION', '2026', 'INGENIERÍA MECÁNICA ELÉCTRICA, ELECTRÓNICA Y SISTEMAS', 'INGENIERÍA DE SISTEMAS', 10000.00, 'DESARROLLO, GESTIÓN, SEGURIDAD Y AUDITORIA DE SISTEMAS DE INFORMACIÓN', 'TICONA YANQUI, FIDEL ERNESTO', '2026-08-04 17:28:45.473000', '2026-08-10 04:03:14.053000', '2026-08-10 04:03:14.074000', 7, 1, NULL, 'Objetivo General:\nAnalizar el riesgo de ciberseguridad estudiantil mediante modelos de inteligencia artificial, identificando factores, patrones y niveles de exposición digital para generar conocimiento y orientar soluciones preventivas en la UNAP\n\nObjetivos Específicos:\n● Identificar los factores de riesgo de ciberseguridad en estudiantes de la Universidad Nacional del Altiplano de Puno, considerando hábitos digitales, contraseñas, información personal, redes, plataformas y dispositivos.\n● Determinar el nivel de riesgo mediante el análisis de amenazas digitales, vulnerabilidades, prácticas de seguridad e incidentes informáticos.\n● Establecer relaciones entre factores de riesgo y comportamientos digitales que aumentan o reducen la vulnerabilidad estudiantil.\n● Aplicar modelos de inteligencia artificial para reconocer patrones, clasificar, predecir o agrupar perfiles de riesgo.\n● Formular lineamientos teóricos y preventivos que orienten futuras acciones de ciberseguridad en estudiantes universitarios.', 'ANÁLISIS DEL RIESGO DE CIBERSEGURIDAD MEDIANTE MODELOS DE INTELIGENCIA ARTIFICIAL EN ESTUDIANTES DE LA UNIVERSIDAD NACIONAL DEL ALTIPLANO DE PUNO, 2026', 'FIDEL ERNESTO TICONA YANQUI', 86.17),
